return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'ወደ ተሰኪ ፍለጋ ይሂዱ','Activate %s' => '%sን አግብር','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> <strong>%2$s</strong> መጫን እና መንቃት ያስፈልገዋል። <a href="%4$s">%3$s</a>','Enter your code here' => 'ኮድዎን እዚህ ያስገቡ','Add %s' => '%s ያክሉ','Remove' => 'አስወግድ','Order number and receipt will be sent to this email address.' => 'የትዕዛዝ ቁጥር እና ደረሰኝ ወደዚህ ኢሜይል አድራሻ ይላካሉ።','Apartment, unit, building, floor, etc.' => 'አፓርትመንት ፣ ክፍል ፣ ህንፃ ፣ ወለል ፣ ወዘተ.','Shipping phone' => 'የማጓጓዣ ስልክ','Only used for shipping-related questions.' => 'ከመርከብ ጋር ለተያያዙ ጥያቄዎች ብቻ ጥቅም ላይ ይውላል።','Single step' => 'ነጠላ ደረጃ','Click to go to the order summary' => 'ወደ የትዕዛዝ ማጠቃለያ ለመሄድ ጠቅ ያድርጉ','Cart total:' => 'የካርታ ጠቅላላ:','Proceed to %s' => 'ወደ %s ይቀጥሉ','Proceed to contact' => 'ለመገናኘት ይቀጥሉ','Proceed to shipping' => 'ወደ መላኪያ ይቀጥሉ','Proceed to billing' => 'ወደ ክፍያ መጠየቂያ ይቀጥሉ','Proceed to payment' => 'ወደ ክፍያ ይቀጥሉ','Shipping method' => 'የማጓጓዣ ዘዴ','Additional notes' => 'ተጨማሪ ማስታወሻዎች','Payment method' => 'የመክፈያ ዘዴ','Step %1$s of %2$s' => 'ደረጃ %1$s ከ%2$s','Change: %s' => 'ለውጥ፡ %s','Not selected yet.' => 'እስካሁን አልተመረጠም።','Same as shipping address' => 'እንደ የመላኪያ አድራሻ ተመሳሳይ','Same as billing address' => 'ከክፍያ መጠየቂያ አድራሻ ጋር ተመሳሳይ','Order summary' => 'የትዕዛዝ ማጠቃለያ','Edit cart' => 'ጋሪ አርትዕ','Did you mean %s?' => '%s ማለትዎ ነውን?','Change email address to: {suggestion-value}' => 'የኢሜይል አድራሻ ወደ፡ {ጥቆማ-እሴት} ቀይር።','This is a required field.' => 'ይህ የሚፈለግ መስክ ነው።','This is not a valid email address.' => 'ይህ ትክክለኛ የኢሜይል አድራሻ አይደለም።','This field does not match the related field value.' => 'ይህ መስክ ከተዛማጅ የመስክ ዋጋ ጋር አይዛመድም።','The CPF number "{cpf_number}" is invalid.' => 'የCPF ቁጥር &quot;{cpf_number}&quot; ልክ ያልሆነ ነው።','The CNPJ number "{cnpj_number}" is invalid.' => 'የCNPJ ቁጥር &quot;{cnpj_number}&quot; ልክ ያልሆነ ነው።','(Required)' => '(የሚያስፈልግ)','Checkout Header - Desktop' => 'Checkout ራስጌ - ዴስክቶፕ','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'ለትልቅ ስክሪኖች መግብሮችን በቼክ መውጫ ራስጌ ላይ አሳይ። የተሰኪውን የቼክ መውጫ ራስጌ ከተጠቀሙ ብቻ ነው የሚታየው።','Checkout Header - Mobile' => 'Checkout ራስጌ - ሞባይል','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'ለሞባይል መሳሪያዎች ከቼክ መውጫ ራስጌ በታች መግብሮችን አሳይ። የተሰኪውን የቼክ መውጫ ራስጌ ከተጠቀሙ ብቻ ነው የሚታየው።','Checkout Sidebar' => 'የጎን አሞሌን ይመልከቱ','Display widgets on the checkout sidebar after the order summary.' => 'ከትዕዛዙ ማጠቃለያ በኋላ መግብሮችን በቼክ መውጫ የጎን አሞሌ ላይ አሳይ።','Checkout Order Summary' => 'የፍተሻ ትዕዛዝ ማጠቃለያ','Display widgets inside the order summary at the checkout page.' => 'በትዕዛዙ ማጠቃለያ ውስጥ መግብሮችን በቼክ መውጫ ገጹ ላይ ያሳዩ።','Checkout Below Place Order' => 'የቦታ ማዘዣን ይመልከቱ','Display widgets below the place order button at the checkout page.' => 'በቼክ መውጫ ገጹ ላይ ከቦታ ማዘዣ ቁልፍ በታች መግብሮችን አሳይ።','Checkout Footer' => 'ግርጌን ይመልከቱ','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'ፍርግሞችን በቼክ መውጫ ግርጌ ላይ አሳይ። የተሰኪውን የቼክ መውጫ ግርጌ ከተጠቀሙ ብቻ ነው የሚታየው።','Classic' => 'ክላሲክ','Boxed' => 'በቦክስ የታሸገ','Split' => 'ተከፈለ','Minimalist' => 'ዝቅተኛነት','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'ፈሳሽ ፍተሻ እና የመላኪያ ቀን ተሰኪዎች በ CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>ለWooCommerce (ነጻ እና PRO) በ CodeRockz የተሰኪውን የመላኪያ እና የመውሰጃ ቀን ጊዜ እየተጠቀሙ መሆኑን ደርሰንበታል። ከእነዚህ ተሰኪዎች ጋር ውህደት ወደ Fluid Checkout PRO ተወስዷል።</p>','Upgrade to PRO' => 'ወደ PRO አሻሽል።','Fluid Checkout database updated successfully' => 'የፈሳሽ Checkout ዳታቤዝ በተሳካ ሁኔታ ተዘምኗል','The database changes where applied successfully.' => 'የውሂብ ጎታው በተሳካ ሁኔታ ሲተገበር ይቀየራል።','Dismiss' => 'አሰናብት','Fluid Checkout database update' => 'የፈሳሽ ቼክአውት ዳታቤዝ ዝማኔ','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'በመረጃ ቋቱ ላይ አንዳንድ ለውጦች ያስፈልጋሉ። እንደማንኛውም ማሻሻያ፣ <strong>ከመቀጠልዎ በፊት የድህረ ገጽዎን ሙሉ ምትኬ እንዲወስዱ</strong> እንመክርዎታለን።','Update database' => 'የውሂብ ጎታ አዘምን','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout ከ Divi Builder የፍተሻ አቀማመጥ ጋር ተኳሃኝ አይደለም።','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>ፈሳሽ ቼክአውት ለመሥራት የሚታወቀው WooCommerce shortcode-based checkout ቅጽ ያስፈልገዋል። የፍተሻ ገጹን ገጽታ እና ስሜት ለማበጀት ዲቪ ገንቢን በሚጠቀሙበት ጊዜ የጥንታዊው አጭር ኮዶች በእያንዳንዱ የፍተሻ ገጹ ክፍል ከዲቪ ገንቢ በተገኙ ብጁ መግብሮች ይተካሉ። እነዚህ ብጁ መግብሮች ከFluid Checkout ጋር ተኳኋኝ አይደሉም።</p><p> እባኮትን የፍተሻ ገጽዎን የዲቪ ግንበኛ መግብሮችን በጽሑፍ መግብር በመተካት አጭር ኮድ <code>[woocommerce_checkout]</code> ያርትዑ።</p>','Edit the checkout page' => 'የፍተሻ ገጹን ያርትዑ','Read the documentation.' => 'ሰነዱን ያንብቡ።','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Fluid Checkout ሲጠቀሙ የጀርመንኛ PRO ባለብዙ ደረጃ ፍተሻ ባህሪን ማሰናከል አለበት።','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Fluid Checkoutን በሚጠቀሙበት ጊዜ፣ ከጀርመናዊው PRO ፕለጊን ያለው ባለብዙ ደረጃ ባህሪ አላስፈላጊ ይሆናል እና <strong>አዳዲስ ትዕዛዞችን በሚሰራበት ጊዜ ወሳኝ ስህተቶችን</strong> ያስከትላል። እባክዎ በፕለጊን ቅንጅቶች ውስጥ በጀርመን የተደረገውን PRO ባለብዙ ደረጃ ፍተሻ ባህሪን ያሰናክሉ።','Go to Germanized settings' => 'ወደ ጀርመንኛ የተደረጉ ቅንብሮች ይሂዱ','Thanks for choosing Fluid Checkout!' => 'ፈሳሽ ቼክአውትን ስለመረጡ እናመሰግናለን!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'አሁን ለተወሰነ ጊዜ ተሰኪውን እየተጠቀሙበት ነው። እስካሁን እንዴት ይወዳሉ?<br> እባኮትን ፈጣን ደረጃ ይስጡን፣ እያንዳንዱን ግብረመልስ እናደንቃለን እና ተሰኪውን ማሻሻል እንድንቀጥል ያበረታታናል :)','Rate the plugin' => 'ተሰኪውን ደረጃ ይስጡት።','I need help!' => 'እርዳታ እፈልጋለሁ!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'አንዳንድ የWooCommerce Checkout Manager በ Quadlayers ባህሪያት በፈሳሽ ቼክአውት ሲጠቀሙበት እንደተጠበቀው ላይሰሩ ይችላሉ። ለበለጠ መረጃ እና አማራጭ መፍትሄዎች <a href="%s">የእኛን ሰነድ</a> ያንብቡ።','Read documentation' => 'ሰነዶችን ያንብቡ','Don\'t show this again' => 'ይህንን እንደገና አታሳይ','Fluid Checkout PRO' => 'ፈሳሽ Checkout PRO','More design templates' => 'ተጨማሪ ንድፍ አብነቶች','Optimized cart page' => 'የተመቻቸ የጋሪ ገጽ','Optimized order received / thank you page' => 'የተመቻቸ ትዕዛዝ ተቀብሏል/አመሰግናለሁ ገጽ','Edit cart contents at checkout page' => 'በቼክ መውጫ ገጽ ላይ የጋሪ ይዘቶችን ያርትዑ','Account matching / user matching' => 'መለያ ማዛመድ / የተጠቃሚ ተዛማጅ','Trust symbols on the cart and thank you pages' => 'በጋሪው ላይ የእምነት ምልክቶች እና የምስጋና ገጾች','More positions for the coupon code on the checkout page' => 'በቼክ መውጫ ገጹ ላይ ለኩፖን ኮድ ተጨማሪ ቦታዎች','International phone numbers' => 'ዓለም አቀፍ የስልክ ቁጥሮች','Gift messages and packing slips' => 'የስጦታ መልእክቶች እና የማሸጊያ ወረቀቶች','Local pickup and in-store collection' => 'የአካባቢ ማንሳት እና በመደብር ውስጥ ስብስብ','EU-VAT Assistant' => 'የአውሮፓ ህብረት-ተእታ ረዳት','I already have it – Hide this offer' => 'አስቀድሜ አለኝ - ይህን አቅርቦት ደብቅ','Activated' => 'ነቅቷል','Address book' => 'የአድራሻ ደብተር','Select an image' => 'ምስል ይምረጡ','Cart layout' => 'የካርታ አቀማመጥ','Cart optimizations' => 'የካርት ማሻሻያዎች','Enable cart page optimizations' => 'የጋሪ ገጽ ማመቻቸትን አንቃ','Header and footer template' => 'ራስጌ እና ግርጌ አብነት','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'ትኩረትን የሚከፋፍሉ ነፃ የገጽ ራስጌ እና ግርጌ መጠቀሙን ይቆጣጠራል ወይም በአሁኑ ጊዜ ንቁ የሆነውን የገጽታ ራስጌ እና ግርጌ ያስቀምጣል።','Distraction free header and footer' => 'ከመረበሽ ነፃ የሆነ ራስጌ እና ግርጌ','Theme\'s header and footer' => 'የገጽታ ራስጌ እና ግርጌ','Cart elements' => 'የካርት አካላት','Make the order summary stay visible on the cart page while scrolling' => 'በማሸብለል ጊዜ የትዕዛዙ ማጠቃለያ በጋሪው ገጽ ላይ እንዲታይ ያድርጉ','Coupon codes' => 'የኩፖን ኮዶች','Hidden' => 'ተደብቋል','Before the cart items section' => 'ከጋሪው እቃዎች ክፍል በፊት','Inside the cart items section' => 'በጋሪው እቃዎች ክፍል ውስጥ','After the cart items section' => 'ከጋሪው እቃዎች ክፍል በኋላ','Before the shipping section' => 'ከማጓጓዣው ክፍል በፊት','After the shipping section' => 'ከማጓጓዣው ክፍል በኋላ','Before the order summary' => 'ከትዕዛዙ ማጠቃለያ በፊት','Inside the order summary' => 'የትዕዛዝ ማጠቃለያ ውስጥ','Before the order totals' => 'ትዕዛዙ ከመጠናቀቁ በፊት','After the order totals' => 'ትዕዛዙ ከተጠናቀቀ በኋላ','After the order summary' => 'ከትዕዛዙ ማጠቃለያ በኋላ','Shipping' => 'መላኪያ','Select position where to display the shipping costs and calculator on the cart page.' => 'በጋሪው ገጽ ላይ የማጓጓዣ ወጪዎችን እና ካልኩሌተርን የሚያሳዩበትን ቦታ ይምረጡ።','Display as a cart section' => 'እንደ ጋሪ ክፍል አሳይ','Cross-sells' => 'ተሻጋሪ-ሽያጭ','Select position where to display the cross-sells section on the cart page.' => 'በጋሪው ገጽ ላይ የሽያጮችን ክፍል የሚያሳዩበትን ቦታ ይምረጡ።','Before the cart actions' => 'ከጋሪው ድርጊቶች በፊት','After the cart actions' => 'ከጋሪው ድርጊቶች በኋላ','Layout of cross-sell items on the cart page.' => 'በጋሪው ገጽ ላይ የሚሸጡ ዕቃዎች አቀማመጥ።','Optimized horizontal cross-sells layout' => 'የተመቻቸ አግድም አግድም-የሽያጭ አቀማመጥ','Theme\'s cross-sells layout' => 'የገጽታ ተሻጋሪ ሽያጭ አቀማመጥ','Number of cross-sell items to display on the cart page' => 'በጋሪው ገጽ ላይ የሚታዩ የተሻገሩ የሚሸጡ ዕቃዎች ብዛት','Add widget areas to the cart page' => 'የመግብር ቦታዎችን ወደ ጋሪው ገጽ ያክሉ','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'እነዚህ መግብር ቦታዎች የታማኝነት ምልክቶችን እና የታመኑ ባጆችን በጋሪው ገጽ ላይ ለመጨመር ያገለግላሉ።','Checkout' => 'ይመልከቱ','Checkout layout' => 'አቀማመጥን ይመልከቱ','Design template' => 'ንድፍ አብነት','Dark mode' => 'ጨለማ ሁነታ','Enable dark mode' => 'ጨለማ ሁነታን አንቃ','Logo image' => 'የአርማ ምስል','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'በቼክ መውጫ ገጽ ራስጌ ላይ የሚታየውን ምስል ይምረጡ። ትኩረትን የሚከፋፍሉ ነፃ ራስጌ እና ግርጌ ሲጠቀሙ ብቻ ነው የሚመለከተው።','Header background color' => 'የራስጌ ዳራ ቀለም','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'ለቼክ መውጫ ገጽ ራስጌ የጀርባ ቀለም ይምረጡ። ትኩረትን የሚከፋፍሉ ነፃ ራስጌ እና ግርጌ ሲጠቀሙ ብቻ ነው የሚመለከተው።','HTML color value. ie: #f3f3f3' => 'የኤችቲኤምኤል ቀለም ዋጋ። ማለትም፡ # f3f3f3','Page background color' => 'የገጽ ዳራ ቀለም','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'ለክፍያ ገጹ የጀርባ ቀለም ይምረጡ። ቀለም <em>በሰውነት</em> አካል ላይ ይተገበራል.','Footer background color' => 'የግርጌ ዳራ ቀለም','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'ለቼክ መውጫ ገጽ ግርጌ የጀርባ ቀለም ይምረጡ። ትኩረትን የሚከፋፍሉ ነፃ ራስጌ እና ግርጌ ሲጠቀሙ ብቻ ነው የሚመለከተው።','Progress bar' => 'የሂደት አሞሌ','Display the checkout progress bar when using multi-step checkout layout' => 'ባለብዙ ደረጃ የፍተሻ አቀማመጥ ሲጠቀሙ የፍተሻ ሂደት አሞሌን ያሳዩ','Make the checkout progress bar stay visible while scrolling' => 'በማሸብለል ጊዜ የፍተሻ ሂደት አሞሌው እንዲታይ ያድርጉ','Express checkout' => 'ፍተሻን ይግለጹ','Enable the express checkout section' => 'ፈጣን የፍተሻ ክፍልን አንቃ','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'የሚደገፉ የክፍያ መግቢያ መንገዶች ይህ ባህሪ ሲነቃ የፈጣን የፍተሻ ክፍልን በፍተሻ ላይ ያሳያል።','Display express checkout buttons in one line for larger screens' => 'ለትላልቅ ስክሪኖች ፈጣን የፍተሻ አዝራሮችን በአንድ መስመር አሳይ','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'ከተኳሃኝ ፈጣን የፍተሻ ክፍያ መግቢያ በር ጋር ሲከፍሉ ተጨማሪ የፍተሻ የሚያስፈልጉ መስኮችን ችላ ይበሉ','Make the order summary stay visible while scrolling' => 'በማሸብለል ጊዜ የትዕዛዙ ማጠቃለያ እንዲታይ ያድርጉ','Choose a background color for the order summary section.' => 'ለትዕዛዙ ማጠቃለያ ክፍል የጀርባ ቀለም ይምረጡ።','Highlight the order totals row in the order summary table' => 'በትእዛዙ ማጠቃለያ ሠንጠረዥ ውስጥ የትዕዛዙን ጠቅላላ ረድፍ ያድምቁ','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'የትዕዛዙ ማጠቃለያ ክፍል የደመቀ የበስተጀርባ ቀለም ከሌለው በጣም ጠቃሚ ነው። Fluid Checkout PROን ሲጠቀሙ ለጋሪው፣ ለተቀበሉት ትዕዛዝ እና የትዕዛዝ ገጾችን ይመልከቱ።','Action link on the order summary at checkout.' => 'በቼክ መውጫ ላይ በትእዛዙ ማጠቃለያ ላይ የእርምጃ አገናኝ።','Edit cart link' => 'የጋሪ አገናኝን ያርትዑ','Cart items count' => 'የካርታ እቃዎች ብዛት','Link to shop page' => 'ወደ የሱቅ ገጽ አገናኝ','Cart items' => 'የካርታ እቃዎች','Hide cart items errors at the checkout page' => 'በቼክ መውጫ ገጹ ላይ የጋሪ እቃዎችን ስህተቶች ደብቅ','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'በቼክ መውጫ ገጹ ላይኛው ክፍል ላይ የጋሪው ንጥሎችን የስህተት መልእክት አታሳይ። ግዢውን ለማጠናቀቅ የፍተሻ ቅጹን በሚያስገቡበት ጊዜ, እነዚህ የስህተት መልዕክቶች ሁልጊዜም ይታያሉ.','Place order' => 'ማዘዙ','Define the position to display "Place order" and terms checkbox section.' => '&quot;የቦታ ቅደም ተከተል&quot; እና የአመልካች ሳጥን ክፍልን ለማሳየት ቦታውን ይግለጹ።','Some options might not be compatible with some plugins and themes.' => 'አንዳንድ አማራጮች ከአንዳንድ ተሰኪዎች እና ገጽታዎች ጋር ተኳሃኝ ላይሆኑ ይችላሉ።','Below the payment section' => 'ከክፍያ ክፍል በታች','Below the order summary' => 'ከትዕዛዙ ማጠቃለያ በታች','Both below the payment section and the order summary' => 'ሁለቱም ከክፍያ ክፍል በታች እና የትዕዛዝ ማጠቃለያ','Add widget areas to the checkout page' => 'የመግብር ቦታዎችን ወደ መውጫ ገጹ ያክሉ','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'እነዚህ መግብር ቦታዎች የእምነት ምልክቶችን እና የእምነት ባጆችን በቼክ መውጫ ገጹ ላይ ለመጨመር ያገለግላሉ።','Display the coupon codes section title' => 'የኩፖን ኮዶች ክፍል ርዕስ አሳይ','Select position where to display the coupon codes section on the checkout page.' => 'በቼክ መውጫ ገጹ ላይ የኩፖን ኮዶች ክፍል የሚታይበትን ቦታ ይምረጡ።','Before the checkout steps' => 'የፍተሻ ደረጃዎች በፊት','As a substep before payment methods' => 'ከመክፈያ ዘዴዎች በፊት እንደ ንዑስ ደረጃ','As a substep after payment methods' => 'ከክፍያ ዘዴዎች በኋላ እንደ ንዑስ ደረጃ','Default button style' => 'ነባሪ የአዝራር ዘይቤ','"Add" link button' => '&quot;አክል&quot; አገናኝ አዝራር','Checkout fields' => 'የፍተሻ መስኮች','Optional fields' => 'አማራጭ መስኮች','Hide optional fields behind a link button' => 'አማራጭ መስኮችን ከአገናኝ ቁልፍ ጀርባ ደብቅ','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'ክፍት የሆኑ የግቤት መስኮችን ቁጥር ለመቀነስ ይህንን አማራጭ ለማጣራት ይመከራል, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">ጥናቱን ያንብቡ</a> .','Do not hide "Address line 2" fields behind a link button' => 'ከአገናኝ ቁልፍ በስተጀርባ &quot;የአድራሻ መስመር 2&quot; መስኮችን አትደብቅ','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'የሚመከር አብዛኛዎቹ ደንበኞች በትክክል የ&quot;አድራሻ መስመር 2&quot; መስክ ሲፈልጉ ወይም ትክክለኛው የመርከብ አድራሻ ሲያገኙ ብቻ ነው (ማለትም ምግብ እና ሌሎች ሊበላሹ የሚችሉ ምርቶችን ካደረሱ)።','Billing address' => 'የመክፈያ አድራሻ','Select position where to display the billing address section on the checkout page.' => 'በፍተሻ ገጹ ላይ የሂሳብ አከፋፈል አድራሻ ክፍሉን የሚያሳዩበትን ቦታ ይምረጡ።','As a step before shipping' => 'ከመርከብዎ በፊት እንደ አንድ ደረጃ','As a sub-step before the shipping address section' => 'ከማጓጓዣው አድራሻ ክፍል በፊት እንደ ንዑስ ደረጃ','As a sub-step after the shipping address section' => 'ከማጓጓዣው አድራሻ ክፍል በኋላ እንደ ንዑስ ደረጃ','As a step after shipping' => 'ከማጓጓዣ በኋላ እንደ አንድ ደረጃ','As a sub-step before the payment section' => 'ከመክፈያው ክፍል በፊት እንደ ንዑስ ደረጃ','Force billing and shipping addresses to the same (single section)' => 'የመክፈያ እና የመላኪያ አድራሻዎችን ወደ ተመሳሳይ (ነጠላ ክፍል) ያስገድዱ','Checkbox for "Same as shipping/billing address" checked by default' => 'አመልካች ሳጥን በነባሪነት ምልክት የተደረገበት &quot;ከመላኪያ/የክፍያ አድራሻ ጋር ተመሳሳይ&quot;','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'የመላኪያ አድራሻው ክፍል መጀመሪያ ሲታይ በነባሪነት ምልክት እንደተደረገበት &quot;እንደ መላኪያ አድራሻ ተመሳሳይ&quot; የሚለው ሳጥን ይጀምራል።<br> አመልካች ሳጥኑ &quot;ከክፍያ መጠየቂያ አድራሻ ጋር አንድ አይነት&quot; የሚጀምረው በነባሪነት የክፍያ መጠየቂያው ክፍል ሲታይ ነው።<br> በቼክ መውጫ ላይ ክፍት የሆኑ የግቤት መስኮችን ቁጥር በከፍተኛ ሁኔታ ለመቀነስ ይህንን አማራጭ በመፈተሽ መተው ይመከራል ፣ <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">ጥናቱን ያንብቡ</a> ።','Highlight the billing address section in the checkout form' => 'የክፍያ መጠየቂያ አድራሻ ክፍሉን በቼክ መውጫ ቅጽ ላይ ያድምቁ','Shipping address' => 'የመላኪያ አድራሻ','Highlight the shipping address section in the checkout form' => 'የማጓጓዣ አድራሻ ክፍሉን በቼክ መውጫ ቅጽ ላይ ያድምቁ','Shipping methods' => 'የማጓጓዣ ዘዴዎች','Choose in which position to display the shipping methods section.' => 'የመላኪያ ዘዴዎች ክፍሉን በየትኛው ቦታ እንደሚያሳዩ ይምረጡ።','Before shipping address' => 'ከመላኪያ አድራሻ በፊት','After shipping address' => 'ከመላኪያ አድራሻ በኋላ','Local pickup' => 'የአካባቢ ማንሳት','Removes shipping address section when a local pickup shipping method is selected.' => 'የአካባቢያዊ የማጓጓዣ ዘዴ ሲመረጥ የመላኪያ አድራሻ ክፍልን ያስወግዳል።','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'የአካባቢያዊ የመርከብ ማጓጓዣ ዘዴ ሲመረጥ የመላኪያ አድራሻውን በተቀማሚው ቦታ ይተካል።','Choose which address to save as the shipping address for local pickup orders.' => 'የትኛውን አድራሻ እንደ ማጓጓዣ አድራሻ ለሀገር ውስጥ መውሰጃ ትዕዛዞች እንደሚያስቀምጡ ይምረጡ።','Save the selected pickup location' => 'የተመረጠውን የመውሰጃ ቦታ ያስቀምጡ','Save same as the billing address' => 'እንደ የክፍያ መጠየቂያ አድራሻ አስቀምጥ','Do not save any shipping address' => 'ማንኛውንም የመላኪያ አድራሻ አታስቀምጥ','Company name field for shipping address' => 'የመላኪያ አድራሻ የኩባንያ ስም መስክ','Change visibility for the company name field for the shipping address section on the checkout form.' => 'በቼክ መውጫ ቅጽ ላይ ላለው የመላኪያ አድራሻ ክፍል ለኩባንያው ስም መስክ ታይነትን ይቀይሩ።','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'መስክ እንደ &quot;አማራጭ&quot; ከተዋቀረ፣ ይህም ነባሪው የታይነት ሁኔታ፣ ሌሎች ፕለጊኖች የሚያስፈልጋቸውን ለውጥ እንዲተገበሩ ምንም አይነት ለውጦች አይተገበሩም።','Hidden (remove field)' => 'የተደበቀ (መስክን ያስወግዱ)','Optional' => 'አማራጭ','Required' => 'ያስፈልጋል','Add shipping phone field to the checkout form.' => 'የማጓጓዣ የስልክ መስክ ወደ ተመዝግቦ መውጫ ቅጽ ያክሉ።','Choose in which step to display the shipping phone field.' => 'የመላኪያ ስልክ መስኩን በየትኛው ደረጃ እንደሚያሳዩ ይምረጡ።','Contact step' => 'የእውቂያ ደረጃ','Billing phone' => 'የሂሳብ አከፋፈል ስልክ','Add billing phone field to the checkout form.' => 'የክፍያ መጠየቂያ የስልክ መስክ ወደ ተመዝግቦ መውጫ ቅጽ ያክሉ።','Choose in which step to display the billing phone field.' => 'የክፍያ መጠየቂያ ስልክ መስኩን በየትኛው ደረጃ እንደሚያሳዩ ይምረጡ።','Show country code beside the flag' => 'የአገር ኮድ ከባንዲራው አጠገብ አሳይ','Show an example of a valid phone number inside phone fields' => 'በስልክ መስኮች ውስጥ የሚሰራ የስልክ ቁጥር ምሳሌ አሳይ','Do not change placeholders' => 'ቦታ ያዥዎችን አይቀይሩ','Show if not defined' => 'ካልተገለጸ አሳይ','Always show' => 'ሁልጊዜ አሳይ','Order notes' => 'የትእዛዝ ማስታወሻዎች','Define the visibility of the additional order notes field.' => 'የተጨማሪ የትዕዛዝ ማስታወሻዎች መስክን ታይነት ይግለጹ።','Gift options' => 'የስጦታ አማራጮች','Allow customers to add a gift message and other gift related options to the order.' => 'ደንበኞች በትእዛዙ ላይ የስጦታ መልእክት እና ሌሎች ከስጦታ ጋር የተያያዙ አማራጮችን እንዲያክሉ ይፍቀዱላቸው።','Display the gift message as part of the order details table instead of a separate section' => 'ከተለየ ክፍል ይልቅ የስጦታ መልዕክቱን እንደ የትዕዛዝ ዝርዝሮች ሰንጠረዥ ያሳዩ','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'ይህ አማራጭ የትዕዛዝ ማረጋገጫ ገጽ (የምስጋና ገጽ) እና የመለያ ገጾች፣ ኢሜይሎች እና የማሸጊያ ወረቀቶች ላይ ዝርዝሮችን ይነካል።','Account matching' => 'መለያ ማዛመድ','Enable the account matching feature' => 'የመለያ ተዛማጅ ባህሪን አንቃ','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'አንድ መለያ አስቀድሞ ከደንበኛው የእውቂያ ዝርዝሮች ጋር ሲኖር የእንግዳ ደንበኛው ትዕዛዞችን ከነባር መለያቸው ጋር ያገናኙ።','Display message when an account exists with the email address provided' => 'ከተሰጠው ኢሜይል አድራሻ ጋር መለያ ሲኖር መልእክት አሳይ','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'የመለያ መፍጠሪያ መስኮችን በማስታወቂያ እና የመግባት አማራጭ ይተካል። በአንዳንድ ሁኔታዎች የደንበኞችን ግላዊነት ለመጠበቅ ይህን አማራጭ እንዳይሰራ መተው ይመከራል።','Dashboard' => 'ዳሽቦርድ','Integrations' => 'ውህደቶች','License keys' => 'የፍቃድ ቁልፎች','Visit our website for more information about our plugins and add-ons.' => 'ስለእኛ ተሰኪዎች እና ተጨማሪዎች ተጨማሪ መረጃ ለማግኘት ድህረ ገጻችንን ይጎብኙ።','Order pay page' => 'የክፍያ ገጽን ማዘዝ','Order pay' => 'ክፍያን ማዘዝ','Enable order pay page optimizations' => 'የትዕዛዝ ክፍያ ገጽ ማሻሻያዎችን አንቃ','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ከደንበኛው ክፍያ በመጠባበቅ ላይ ላሉት ነባር ትዕዛዞች የትዕዛዝ ክፍያ ገጽን አቀማመጥ ይለውጣል።','Add widget areas to the order pay page' => 'የመግብር ቦታዎችን ወደ የትዕዛዝ ክፍያ ገጽ ያክሉ','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'እነዚህ መግብር ቦታዎች በትዕዛዝ ክፍያ ገጽ ላይ የእምነት ምልክቶችን እና የእምነት ባጆችን ለመጨመር ያገለግላሉ።','Thank you page & order details layout' => 'እናመሰግናለን ገጽ እና ዝርዝሮች አቀማመጥ','Order details optimizations' => 'የትዕዛዝ ዝርዝሮች ማትባቶች','Enable thank you page and order details optimizations' => 'የምስጋና ገጽን አንቃ እና ዝርዝር ማሻሻያዎችን ይዘዙ','Changes the layout of order details on the thank you page and account pages.' => 'የምስጋና ገጽ እና የመለያ ገጾች ላይ የትዕዛዝ ዝርዝሮችን አቀማመጥ ይለውጣል።','Enable order details customizations on email notifications' => 'በኢሜይል ማሳወቂያዎች ላይ የትዕዛዝ ዝርዝሮችን ማበጀትን ያንቁ','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'በኢሜል ማሳወቂያዎች ላይ አዲስ ክፍሎችን ያሳዩ እና የክፍሎችን ቅደም ተከተል ይለውጡ። በኢሜይል ማሳወቂያዎች ላይ የትዕዛዝ ዝርዝሮች ቅጦች አልተለወጡም።','Thank you page' => 'እናመሰግናለን ገጽ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'እነዚህ አማራጮች የምስጋና ገጽ ላይ ተጽዕኖ ያሳድራሉ፣ እንዲሁም የተቀበሉት ትዕዛዝ ወይም የማረጋገጫ ገጾች በመባል ይታወቃል።','Order details layout' => 'የትዕዛዝ ዝርዝሮች አቀማመጥ','Display the order details with wide layout on the thank you page' => 'የምስጋና ገጽ ላይ የትዕዛዝ ዝርዝሮችን በሰፊው አቀማመጥ አሳይ','Add widget areas to the thank you page' => 'ወደ የምስጋና ገጽ መግብር ቦታዎችን ያክሉ','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'እነዚህ መግብር ቦታዎች የእምነት ምልክቶችን እና የእምነት ባጆችን በምስጋና ገጽ ላይ ለመጨመር ያገለግላሉ።','Order actions' => 'እርምጃዎችን ይዘዙ','Choose in which position to display the order actions.' => 'የትዕዛዝ እርምጃዎችን በየትኛው ቦታ እንደሚያሳዩ ይምረጡ።','Inside the order overview' => 'በትእዛዙ አጠቃላይ እይታ ውስጥ','After the order overview' => 'ከትዕዛዙ አጠቃላይ እይታ በኋላ','After order sections' => 'ከትዕዛዝ ክፍሎች በኋላ','Order status' => 'የትዕዛዝ ሁኔታ','Display the order status progress bar' => 'የትዕዛዝ ሁኔታ ሂደት አሞሌን አሳይ','Choose in which position to display the section.' => 'ክፍሉን ለማሳየት በየትኛው ቦታ ላይ ይምረጡ.','After the order overview and payment instructions' => 'ከትዕዛዝ አጠቃላይ እይታ እና የክፍያ መመሪያዎች በኋላ','Before the order items section' => 'ከትዕዛዝ እቃዎች ክፍል በፊት','Inside the order items section' => 'በትእዛዝ ዕቃዎች ክፍል ውስጥ','After the order items section' => 'ከትዕዛዝ እቃዎች ክፍል በኋላ','On the sidebar' => 'በጎን አሞሌ ላይ','Order downloads' => 'ውርዶችን ይዘዙ','Gift message' => 'የስጦታ መልእክት','Tools' => 'መሳሪያዎች','Troubleshooting' => 'መላ መፈለግ','Debug options' => 'የማረም አማራጮች','Debug mode' => 'የማረም ሁነታ','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'የማረም ሁነታን መጠቀም የድር ጣቢያውን አፈጻጸም ይጎዳል። መላ በሚፈልጉበት ጊዜ ይህንን አማራጭ ብቻ ይጠቀሙ።','Load unminified assets' => 'ያልተወሳሰቡ ንብረቶችን ጫን','Enhanced select fields' => 'የተሻሻሉ የተመረጡ መስኮች','Fix automatic zoom-in on form fields' => 'በቅጽ መስኮች ላይ ራስ-ሰር ማጉላትን ያስተካክሉ','Set <code>font-size</code> inside form fields to 16px' => '<code>font-size</code> በቅጽ መስኮች ወደ 16 ፒክስል ያዘጋጁ','Fluid Checkout' => 'ፈሳሽ ቼክአውት','Settings' => 'ቅንብሮች','Support' => 'ድጋፍ','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'ተጨማሪ አማራጮችን ለመክፈት <a target="_blank" href="%s">ወደ PRO ያሻሽሉ</a> ።','(PRO)' => '(PRO)','(experimental)' => '(የሙከራ)','Please verify your phone number.' => 'እባክዎን ስልክ ቁጥርዎን ያረጋግጡ።','The Bluehost Plugin' => 'የብሉሆስት ተሰኪ','Custom fields' => 'ብጁ መስኮች','Enable custom shipping email field' => 'ብጁ የመላኪያ ኢሜይል መስክን አንቃ','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'ሲነቃ ከብሉሆስት ተሰኪው የመላኪያ ኢሜል መስኩ ወደ ቼክ መውጫው ይታከላል።','Captcha Pro by BestWebSoft' => 'Captcha Pro በ BestWebSoft','Captcha position' => 'Captcha አቀማመጥ','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'የ captcha ክፍልን ለማሳየት ቦታውን ይግለጹ. በተመረጠው የካፒቻ አይነት ላይ በመመስረት አንዳንድ ቦታዎች ላይሰሩ ይችላሉ።','Selecting a pickup point is required before proceeding.' => 'ከመቀጠልዎ በፊት የመውሰጃ ነጥብ መምረጥ ያስፈልጋል.','Pickup point' => 'የመውሰጃ ነጥብ','Pickup point not selected yet.' => 'የመውሰጃ ነጥብ ገና አልተመረጠም።','Pickup point:' => 'የመውሰጃ ነጥብ፡-','Mailchimp for WooCommerce' => 'ሜልቺምፕ ለWooCommerce','Subscribe checkbox' => 'ለደንበኝነት ይመዝገቡ አመልካች ሳጥን','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'የደንበኝነት ተመዝጋቢ አመልካች ሳጥኑን በቼክ መውጫ ገጹ ላይ ይሽሩት እና ሁልጊዜ በእውቂያ ደረጃ ላይ ያሳዩት።','Before Shipping Address' => 'ከመላኪያ አድራሻ በፊት','(originally "%s")' => '(በመጀመሪያ &quot;%s&quot;)','After Shipping Address' => 'ከማጓጓዣ አድራሻ በኋላ','Selecting a collection point is required when shipping with FermoPoint.' => 'በ FermoPoint ሲላክ የመሰብሰቢያ ቦታ መምረጥ ያስፈልጋል።','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'ምልክት የተደረገበት ከሆነ ለተጠቃሚዎች የኢሜል ስህተቶችን ያሳውቃል። (ይህ ባህሪው ተሰናክሏል ምክንያቱም Fluid Checkout ባህሪውን ያቀርባል። በዚህ አማራጭ ላይ የሚደረጉ ለውጦች አይተገበሩም)','Enable Mail Check: (disabled feature)' => 'የደብዳቤ ፍተሻን አንቃ (የተሰናከለ ባህሪ)','Carrier:' => 'ተሸካሚ','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce ኢሜይል ማርኬቲንግ','Sign up checkbox position' => 'የአመልካች ሳጥን አቀማመጥ ይመዝገቡ','Move the sign up checkbox to the contact step' => 'የምዝገባ አመልካች ሳጥኑን ወደ የእውቂያ ደረጃ ይውሰዱት።','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'ሲነቃ አመልካች ሳጥኑ በ Sendinblue ፕለጊን ቅንጅቶች ውስጥ ከተገለጸው የማሳያ ቦታ ተለይቶ ወደ የእውቂያ ደረጃ ይንቀሳቀሳል።','Theme Betheme' => 'ጭብጥ ቤቲሜ','Checkout progress' => 'ሂደትን ይመልከቱ','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'የቼክ መውጫ ደረጃዎችን ክፍል ከቤቴሜ በቼክ መውጫ፣ በጋሪ እና በተቀበሉት ገጾች ላይ ያውጡ።','Theme Fennik' => 'ጭብጥ Fennik','Breadcrumbs' => 'የዳቦ ፍርፋሪ','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Fluid Checkout ራስጌ እና ግርጌ ሲጠቀሙ የዳቦ ፍርፋሪውን ክፍል ከ Fennik ጭብጥ ያውጡት።','Theme Go' => 'ጭብጥ ሂድ','My account layout' => 'የእኔ መለያ አቀማመጥ','Enable wide layout on "My account" page.' => 'በ &quot;የእኔ መለያ&quot; ገጽ ላይ ሰፊ አቀማመጥን አንቃ።','Theme Impreza' => 'ጭብጥ ኢምፕሬዛ','Header' => 'ራስጌ','Spacing for site header at the checkout page (in pixels)' => 'በፍተሻ ገጹ ላይ ለጣቢያ ራስጌ ክፍተት (በፒክሴል)','Only applicable when using the Impreza theme header at the checkout page.' => 'በቼክ መውጫ ገጹ ላይ የ Impreza ጭብጥ ራስጌን ሲጠቀሙ ብቻ ነው የሚመለከተው።','Theme Kapee' => 'ጭብጥ ካፔ','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'የፍተሻ ደረጃዎች ክፍልን ከ Kapee ጭብጥ በቼክአውት ፣ በጋሪው እና በተቀበሉት ገጾች ላይ ያውጡ።','Theme Porto' => 'ጭብጥ ፖርቶ','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'የፍተሻ ደረጃዎች ክፍልን ከፖርቶ ጭብጥ በቼክአውት ፣ በጋሪው እና በተቀበሉት ገጾች ላይ ያውጡ።','Theme Pressmart' => 'ጭብጥ Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'የፍተሻ ደረጃዎች ክፍልን ከፕሬስማርት ጭብጥ በቼክ መውጫ፣ በጋሪው እና በተቀበሉት ገጾች ላይ ያውጡ።','Theme The Gem' => 'The Gem ጭብጥ','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Fluid Checkout ራስጌ እና ግርጌ በሚጠቀሙበት ጊዜ ከጌም ጭብጥ የፍተሻ ደረጃዎች ክፍልን ያውጡ።','Theme Woodmart' => 'ጭብጥ Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Fluid Checkout ራስጌ እና ግርጌ ሲጠቀሙ የፍተሻ ደረጃዎች ክፍልን ከዉድማርት ጭብጥ ያውጡ።','Checkout options' => 'የፍተሻ አማራጮች','Disable the theme checkout options' => 'የገጽታ መውጫ አማራጮችን አሰናክል','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'አማራጮቹ የምርት ምስልን፣ የብዛት መስክን፣ የማስወገድ ቁልፍን እና በጭብጡ የተጨመረውን የምርት ገጽ ማገናኘት በነባሪነት ተሰናክለዋል።','Theme Atomion' => 'ጭብጥ Atomion','Order progress' => 'የትዕዛዝ ሂደት','Display order progress from the theme' => 'ከጭብጡ የትዕዛዝ ሂደት አሳይ','Display the form field labels visible on the page' => 'በገጹ ላይ የሚታዩ የቅጽ መስክ መለያዎችን አሳይ','It is recommended to keep this option enabled for a better user experience.' => 'ለተሻለ የተጠቃሚ ተሞክሮ ይህንን አማራጭ እንደነቃ ለማቆየት ይመከራል።','Theme ZK Nito' => 'ጭብጥ ZK Nito','Add extra fields to the checkout form' => 'ተጨማሪ መስኮችን ወደ ተመዝግቦ መውጫ ቅጽ ያክሉ','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'ተጨማሪ የመላኪያ ኢሜይል እና የመላኪያ የስልክ መስክ ወደ የመላኪያ አድራሻ ክፍል ያክላል።','Go to the home page' => 'ወደ መነሻ ገጽ ይሂዱ','Skip to content' => 'ወደ ይዘት ዝለል','Create an account' => 'መለያ ፍጠር','Log in to your account' => 'ወደ መለያዎ ይግቡ','Already have an account?' => 'መለያ አለህ?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'እንደ %1$s ገብቷል። <a href="%2$s">ውጣ</a>','Your order has a total amount due of %s. No further payment is needed.' => 'የትዕዛዝዎ ጠቅላላ መጠን በ%s ምክንያት አለው። ምንም ተጨማሪ ክፍያ አያስፈልግም.','Close and continue with checkout' => 'ዝጋ እና በቼክ መውጣት ይቀጥሉ','Continue' => 'ቀጥል','Parcel terminal' => 'የፓርሴል ተርሚናል','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>ይህ መግብር በፈሳሽ ቼክአውት ተተክቷል።</p><p> Fluid Checkout በሚጠቀሙበት ጊዜ የፍተሻ ገጹ በትክክል ለመስራት ዋናውን WooCommerce shortcode <code>[woocommerce_checkout]</code> መጠቀም አለበት።</p><p> ለበለጠ መረጃ፣ የፈሳሽ ፍተሻ ሰነድን ይጎብኙ።</p>','Theme The7' => 'ጭብጥ 7','Additional header sections' => 'ተጨማሪ የራስጌ ክፍሎች','Output additional header sections if enabled in the theme settings.' => 'በገጽታ ቅንጅቶች ውስጥ ከነቃ ተጨማሪ የራስጌ ክፍሎችን ያውጡ።','More information' => 'ተጨማሪ መረጃ','Pick a Locker' => 'መቆለፊያ ይምረጡ','Page template' => 'የገጽ አብነት','Use `Order confirmation` page template for block-based themes' => 'በብሎክ ላይ ለተመሰረቱ ገጽታዎች የ‹ትዕዛዝ ማረጋገጫ› ገጽ አብነት ይጠቀሙ','Only applies when using a block-based theme.' => 'በብሎክ ላይ የተመሰረተ ጭብጥ ሲጠቀሙ ብቻ ነው የሚመለከተው።','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'የክፍያ ቅጽ','Apply styles to the Stripe payment form fields' => 'ቅጦችን ወደ Stripe የክፍያ ቅጽ መስኮች ተግብር','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'ሲነቃ Fluid Checkout ከተሰኪው ጋር ተኳሃኝነት የተመቻቹ ቅጦችን ይተገበራል። ለ Stripe የክፍያ ቅጽ መስኮች ብጁ ቅጦችን እየተጠቀሙ ከሆነ ይህንን ማሰናከል ይፈልጉ ይሆናል።','Theme Nyture' => 'ጭብጥ Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Fluid Checkout በሚጠቀሙበት ጊዜ የፍተሻ ደረጃዎች ክፍሉን ከናይture ጭብጥ ያውጡ።','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'ደንበኞች በመደብሩ አስተዳዳሪ በእጅ ለተፈጠሩ ወይም በፍተሻ ጊዜ ላልተጠናቀቁ ትዕዛዞች ክፍያ እንዲፈጽሙ ይፈቅዳል።','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'ፕለጊኑ WooCommerce Checkout Manager by Quadlayers ከ Fluid Checkout ጋር ተኳሃኝ አይደለም።','Company name field for billing address' => 'የኩባንያ ስም መስክ ለክፍያ መጠየቂያ አድራሻ','Change visibility for the company name field for the billing address section on the checkout form.' => 'በቼክ መውጫ ፎርሙ ላይ ላለው የክፍያ መጠየቂያ አድራሻ ክፍል ለኩባንያው ስም መስክ ታይነትን ይቀይሩ።','Theme Bookshelf' => 'ጭብጥ የመጽሐፍ መደርደሪያ','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'ፈሳሽ ቼክአውትን በሚጠቀሙበት ጊዜ የፍተሻ ደረጃዎች ክፍልን ከመጽሃፍ መደርደሪያው ጭብጥ ያውጡ።','Account password' => 'የመለያ ይለፍ ቃል','An account will be created with the information provided at checkout when completing the order.' => 'ትዕዛዙን ሲያጠናቅቁ ተመዝግበው ሲወጡ ከተሰጠው መረጃ ጋር መለያ ይፈጠራል።','Choose the style of the progress bar.' => 'የሂደት አሞሌውን ዘይቤ ይምረጡ።','Bars' => 'ቡና ቤቶች','Theme Ireca' => 'ጭብጥ ኢሬካ','WooCommerce page layout' => 'WooCommerce ገጽ አቀማመጥ','Force wide layout on WooCommerce pages' => 'WooCommerce ገጾች ላይ ሰፊ አቀማመጥን አስገድድ','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'ይህ በ WooCommerce ገፆች ላይ የይዘት ክፍሉ በጣም ጠባብ እንዳልሆነ ያረጋግጣል፣ ቼክ መውጫ፣ ጋሪ፣ የተቀበሉት ትዕዛዝ፣ ክፍያ ማዘዣ እና የመለያ ገጾች።','WooCommerce Smart Coupons' => 'WooCommerce ስማርት ኩፖኖች','Position on checkout page' => 'በቼክ መውጫ ገጽ ላይ አቀማመጥ','Choose where to display the available coupons section on the checkout page.' => 'በቼክ መውጫ ገጹ ላይ ያለውን የኩፖኖች ክፍል የት እንደሚታይ ይምረጡ።','Before the progress bar' => 'ከሂደቱ አሞሌ በፊት','After the progress bar' => 'ከሂደት አሞሌ በኋላ','Before coupon codes section' => 'ከኩፖን ኮዶች ክፍል በፊት','Format phone numbers according to the rules for each country.' => 'በእያንዳንዱ ሀገር ደንቦች መሰረት የስልክ ቁጥሮችን ይቅረጹ.','Use precise phone number validation' => 'ትክክለኛ የስልክ ቁጥር ማረጋገጫ ተጠቀም','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'ይህ የሙከራ ባህሪ ነው እና በሁሉም ውቅሮች ውስጥ እንደተጠበቀው ላይሰራ ይችላል። በጥንቃቄ ይጠቀሙበት.','Phone number validation types used when precise validation is enabled.' => 'ትክክለኛ ማረጋገጫ ሲነቃ ጥቅም ላይ የሚውሉ የስልክ ቁጥር ማረጋገጫ ዓይነቶች።','Mobile' => 'ሞባይል','Fixed line' => 'ቋሚ መስመር','Toll free' => 'ከክፍያ ነፃ','Contact' => 'እውቂያ','Multi step' => 'ባለብዙ ደረጃ','2 columns' => '2 አምዶች','1 column' => '1 አምድ','Before checkout steps' => 'ከክፍያ በፊት ደረጃዎች','Or' => 'ወይም','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'የ <em>&quot;1 አምድ&quot;</em> የቼክ መውጫ አቀማመጥን ሲጠቀሙ ይህ አማራጭ ሁልጊዜ <em>&quot;ከቼክ መውጫ ደረጃዎች በፊት&quot;</em> ተብሎ የሚቀናበር ሲሆን ለዴስክቶፕ እይታም ይሠራል።','Position for the extra order summary section on mobile.' => 'በሞባይል ላይ ለተጨማሪ ትዕዛዝ ማጠቃለያ ክፍል ቦታ።','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;በጣቢያው ላይ ያለው ራስጌ&quot;</em> የሚለው አማራጭ የሚተገበረው ትኩረትን የሚከፋፍል ራስጌን ሲጠቀሙ ብቻ ነው።','On the site header (requires distraction-free header)' => 'በጣቢያው ራስጌ ላይ (ትኩረትን የማያከፋፍል ራስጌ ያስፈልገዋል)','Initial state for the expansible order summary section on mobile.' => 'በሞባይል ላይ ለሚሰፋው የትዕዛዝ ማጠቃለያ ክፍል የመጀመሪያ ሁኔታ።','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'በተቆጣጣሪ መስፈርቶች ምክንያት ለሚከተሉት አገሮች <em>እንደተስፋፋ</em> እንዲያዘጋጁት እንመክራለን <strong>፡ ጀርመን</strong> ፣ <strong>ኦስትሪያ</strong> ፣ <strong>ስዊዘርላንድ</strong> ፣ <strong>ኔዘርላንድስ</strong> ፣ <strong>ፖላንድ</strong> ፣ <strong>ቤልጂየም</strong> እና <strong>ፈረንሳይ</strong> ።','Collapsed' => 'ተሰብስቧል','Expanded' => 'ተዘርግቷል','Do not show' => 'አታሳይ','yes' => 'አዎ','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'የክፍያ አድራሻ ክፍሉ ከማጓጓዣ አድራሻ ክፍል በኋላ ከታየ እና የክፍያ ስልክ መስኩ &quot;አስፈላጊ&quot; ከሆነ የማጓጓዣ ስልክ መስኩ &quot;አስፈላጊ&quot; ተብሎ ሊገደድ ይችላል። ይህ አማራጭ ሲረጋገጥ የማጓጓዣ አድራሻው ወደ የክፍያ አድራሻው ሊገለበጥ እንደሚችል ለማረጋገጥ ያስፈልጋል፣ አለበለዚያ ደንበኛው የክፍያ ቅጽን መሙላት ላይችል ይችላል።','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'የክፍያ አድራሻው ክፍል ከማጓጓዣ አድራሻው ክፍል በፊት ከታየ እና የማጓጓዣ ስልክ መስኩ &quot;አስፈላጊ&quot; ከሆነ የክፍያ ስልክ መስኩ &quot;አስፈላጊ&quot; ተብሎ ሊገደድ ይችላል። ይህ አማራጭ ሲረጋገጥ የማጓጓዣ አድራሻው ወደ የክፍያ አድራሻው ሊገለበጥ እንደሚችል ለማረጋገጥ ያስፈልጋል፣ አለበለዚያ ደንበኛው የክፍያ ቅጽን መሙላት ላይችል ይችላል።','Settings profiles' => 'የቅንብሮች መገለጫዎች','Settings profile' => 'የቅንብሮች መገለጫ','You do not have permission to perform this action.' => 'ይህንን እርምጃ የመፈጸም ፈቃድ የለህም።','You do not have permission to activate plugins.' => 'ተሰኪዎችን ለማግበር ፈቃድ የለዎትም።','Missing plugin.' => 'የጠፋ ተሰኪ።','Plugin activated.' => 'ተሰኪው ነቅቷል።','The following changes will be applied:' => 'የሚከተሉት ለውጦች ይተገበራሉ፦','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'ከ Fluid Checkout 5.0 ጀምሮ፣ ቅንብሮች በተለየ መንገድ ይቀመጣሉ። አስፈላጊ ከሆነ ወደ ቀዳሚ ስሪቶች እንዲወርዱ ለማድረግ የቆዩ አማራጮች አሁንም በመረጃ ቋቱ ውስጥ ይቀመጣሉ።','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'መደብርዎ በአዲሶቹ ቅንብሮች ላይ ለሁለት ሳምንታት ያህል ሲሰራ ቆይቷል፣ ስለዚህ በመረጃ ቋቱ ውስጥ የተከማቹ የቆዩ አማራጮችን ማጽዳት ይችላሉ። እባክዎ ከጽዳት በኋላ፣ ወደ ቀደሙት የፕለጊኑ ስሪቶች ዝቅ ማድረግ ከፈለጉ ለሁሉም ቅንብሮች ነባሪ እሴቶችን እንደሚጠቀም ልብ ይበሉ።','Fluid Checkout settings cleanup' => 'የፈሳሽ ፍተሻ ቅንብሮችን ማጽዳት','Delete leftover options' => 'የቀሩትን አማራጮች ሰርዝ','Help us improve Fluid Checkout' => 'የፈሳሽ ክፍያን ለማሻሻል ያግዙን','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'ፈጣን ድጋፍ ለማግኘት እና ተኳሃኝነትን ለማሻሻል እና ተጽዕኖን ለመለካት እንዲረዳን ስም-አልባ የጣቢያ አካባቢ ሪፖርቶችን በFluid Checkout ያጋሩ። ምንም ደንበኛ፣ ተጠቃሚ ወይም ሚስጥራዊ መረጃ አልተካተተም። በማንኛውም ጊዜ ከመሳሪያዎች ቅንብሮች ውስጥ ምን እንደሚጋራ መምረጥ ይችላሉ።','Enable site environment reports' => 'የጣቢያ አካባቢ ሪፖርቶችን ያንቁ','Review settings' => 'ቅንብሮችን ይገምግሙ','This preview has expired. Reload the admin page to start a new preview.' => 'ይህ ቅድመ እይታ ጊዜው አልፎበታል። አዲስ ቅድመ እይታ ለመጀመር የአስተዳዳሪ ገጹን እንደገና ይጫኑ።','Preview expired' => 'ቅድመ እይታ ጊዜው አልፎበታል','Orders cannot be placed in the preview.' => 'ትዕዛዞች በቅድመ እይታ ውስጥ ሊቀመጡ አይችሉም።','Logging in is not available in the preview.' => 'በቅድመ እይታው ውስጥ መግባት አይገኝም።','Accounts cannot be created in the preview.' => 'መለያዎች በቅድመ እይታ ውስጥ ሊፈጠሩ አይችሉም።','Requests to other sites are blocked in the preview.' => 'ወደ ሌሎች ጣቢያዎች የሚደረጉ ጥያቄዎች በቅድመ እይታው ውስጥ ታግደዋል።','Processing…' => 'በማስኬድ ላይ…','Something went wrong. Please try again.' => 'የሆነ ችግር ተፈጥሯል። እባክዎ እንደገና ይሞክሩ።','Activate plugin' => 'ተሰኪውን ያግብሩ','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - የተሟላ የቼክአውት ጥቅል','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'ሁሉም የፕሮ ፕሮ ባህሪያት + ሁሉም ተጨማሪዎች፣ አንድ ዋጋ። የዲዛይን አብነቶች፣ የተመቻቹ የጋሪ እና የተቀበሉ ገጾች፣ የመለያ ማመሳሰል እና ብዙ ተጨማሪ ነገሮች።','Optimized order pay page' => 'የተመቻቸ የትዕዛዝ ክፍያ ገጽ','Express checkout buttons from supported payment methods' => 'ከሚደገፉ የክፍያ ዘዴዎች ፈጣን የቼክ መውጫ አዝራሮች','Delayed account creation' => 'የመለያ ፈጠራ ዘግይቷል','Address autocomplete with Google Maps APIs' => 'አድራሻውን በራስ-ሰር ያጠናቅቁ በGoogle Maps APIs','Multiple saved addresses with the address book' => 'ከአድራሻ ደብተር ጋር በርካታ የተቀመጡ አድራሻዎች','EU-VAT assistant' => 'የአውሮፓ ህብረት-ቫት ረዳት','Hide this section' => 'ይህንን ክፍል ደብቅ','Learn more' => 'ተጨማሪ ይወቁ','Get early access' => 'ቀደም ያለ መዳረሻ ያግኙ','Activate add-on' => 'ተጨማሪውን ያግብሩ','Get more out of your checkout journey' => 'ከቼክ መውጫ ጉዞዎ የበለጠ ያግኙ','Test API key' => 'የኤፒአይ ቁልፍን ይሞክሩ','Guided setup' => 'የሚመራ ማዋቀር','Options' => 'አማራጮች','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">በቼክ መውጫ አማራጮች</a> ላይ አቀማመጥ እና ዲዛይን ያዘጋጁ።','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'የእንግዳ ክፍያ መፈጸምን ያንቁ እና/ወይም <a href="%s">የደንበኛ መለያዎች ቅንብሮችን</a> ይገምግሙ።','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'የተመቻቸ <a href="%1$s">ጋሪን</a> ያንቁ፣ <a href="%2$s">አመሰግናለሁ</a> እና <a href="%3$s">የክፍያ ገጾችን ይዘዙ</a> ።','Enable <a href="%s">address autocomplete</a> from Google Maps.' => '<a href="%s">የአድራሻ ራስ-ሰር ማጠናቀቂያን</a> ከGoogle ካርታዎች ያንቁ።','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">በአድራሻ ደብተር</a> አማካኝነት በርካታ የተቀመጡ አድራሻዎችን ያንቁ።','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'ለጭብጡ ወይም ለሌሎች የጫኑዋቸው ተሰኪዎች የሚገኙ <a href="%s">የውህደት አማራጮች</a> ካሉ ያረጋግጡ።','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'ፈጣን ድጋፍ ያግኙ እና ተኳሃኝነትን ለማሻሻል እና ተጽዕኖን ለመለካት ያግዙን። ከመሳሪያዎች ቅንብሮች <a href="%s">የአጠቃቀም ክትትልን ያንቁ</a> ።','Missing settings tab.' => 'የቅንብሮች ትር ይጎድላል።','Getting started' => 'እንደ መጀመር','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>በጣም ጥሩ! የቼክአውት ገጽዎ አሁን በFluid Checkout ላይ እየሰራ ነው።</strong> ለመጀመር ጥቂት ደረጃዎች እነሆ','Completed' => 'ተጠናቋል','Preview report data' => 'የሪፖርት ውሂብን አስቀድመው ይመልከቱ','Send now' => 'አሁን ይላኩ','Auto-detect' => 'በራስ-ሰር ፈልግ','Afrikaans' => 'አፍሪካንስ','Albanian' => 'አልበንያኛ','Amharic' => 'አማርኛ','Arabic' => 'አረብኛ','Armenian' => 'አርመንያኛ','Azerbaijani' => 'አዘርባጃኒኛ','Basque' => 'ባስክ','Belarusian' => 'ቤላሩሲያን','Bengali' => 'ቤንጋሊ','Bosnian' => 'ቦስንያን','Bulgarian' => 'ቡልጋርያኛ','Burmese' => 'በርሚስ','Catalan' => 'ካታሊያን','Chinese' => 'ቻይንኛ','Chinese (Simplified)' => 'ቻይንኛ (ቀለል ያለ)','Chinese (Hong Kong)' => 'ቻይንኛ (ሆንግ ኮንግ)','Chinese (Traditional)' => 'ቻይንኛ (ባህላዊ)','Croatian' => 'ክሮኤሽያን','Czech' => 'ቼክ','Danish' => 'ዳኒሽ','Dutch' => 'ደች','English' => 'እንግሊዝኛ','English (Australian)' => 'እንግሊዝኛ (አውስትራሊያ)','English (Great Britain)' => 'እንግሊዝኛ (ታላቋ ብሪታንያ)','Estonian' => 'ኢስቶኒያን','Farsi' => 'ፋርሲ','Finnish' => 'ፊኒሽ','Filipino' => 'ፊሊፒናዊ','French' => 'ፈረንሳይኛ','French (Canadian)' => 'ፈረንሳይኛ (ካናዳዊ)','Galician' => 'ጋላሺያን','Georgian' => 'ጆርጅያን','German' => 'ጀርመንኛ','Greek' => 'ግሪክኛ','Gujarati' => 'ጉጅራቲ','Hebrew' => 'ሂብሩ','Hindi' => 'ሂንዲ','Hungarian' => 'ሃንጋሪያን','Icelandic' => 'አይስላንዲ ክ','Indonesian' => 'ኢንዶኔዥያን','Italian' => 'ጣሊያንኛ','Japanese' => 'ጃፓንኛ','Kannada' => 'ካናዳ','Kazakh' => 'ካዛክሀ','Khmer' => 'ክመር','Korean' => 'ኮሪያኛ','Kyrgyz' => 'ክይርግያዝ','Lao' => 'ላኦ','Latvian' => 'ላትቪያን','Lithuanian' => 'ሊቱኒያን','Macedonian' => 'ማስዶንያን','Malay' => 'ማላይ','Malayalam' => 'ማላያላም','Marathi' => 'ማራቲ','Mongolian' => 'ሞኒጎሊያን','Nepali' => 'ኔፓሊ','Norwegian' => 'ኖርወይኛ','Polish' => 'ፖሊሽ','Portuguese' => 'ፖርቹጋልኛ','Portuguese (Brazil)' => 'ፖርቱጋልኛ (ብራዚል)','Portuguese (Portugal)' => 'ፖርቱጋልኛ (ፖርቱጋል)','Punjabi' => 'ፑንጃቢ','Romanian' => 'ሮማንያን','Russian' => 'ራሺያኛ','Serbian' => 'ሰሪቢያን','Sinhalese' => 'ሲንሃሌዝኛ','Slovak' => 'ስሎቫክ','Slovenian' => 'ስሎቬንያን','Spanish' => 'ስፓንኛ','Spanish (Latin America)' => 'ስፓኒሽ (ላቲን አሜሪካ)','Swahili' => 'ስዋሕሊ','Swedish' => 'ስዊድንኛ','Tamil' => 'ታሚል','Telugu' => 'ተሉጉ','Thai' => 'ታይ','Turkish' => 'ቱሪክሽ','Ukrainian' => 'ዩክሬንያን','Urdu' => 'ኡርዱ','Vietnamese' => 'ቪትናሜሴ','Zulu' => 'ዙሉ','Google address autocomplete' => 'የጉግል አድራሻ ራስ-ሰር አጠናቅቅ','Google Places API version' => 'የጉግል ቦታዎች ኤፒአይ ስሪት','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'የትኛውን የGoogle Places API ስሪት እንደሚጠቀሙ ይምረጡ። በተቻለ ፍጥነት ወደ አዲሱ Places API እንዲዛወሩ እንመክራለን።','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'ከማርች 1፣ 2025 ጀምሮ &quot;Places API (New)&quot; የሚለውን ስሪት እንዲጠቀሙ እንመክራለን። ጉግል &quot;Places API (Legacy)&quot; የሚለውን ስሪት ወደ Legacy ሁኔታ ያንቀሳቅሰዋል፣ ይህም ማለት ይህንን አገልግሎት ለአዲስ የኤፒአይ ቁልፎች ማንቃት አይችሉም እና የኤፒአይው ስሪት በመጨረሻ አይገኝም ማለት ነው። ቀድሞውኑ Legacy API ን የሚጠቀሙ ነባር መለያዎች ያለ ምንም መቆራረጥ መስራታቸውን ሊቀጥሉ ይችላሉ።','(Recommended)' => '(የሚመከር)','Google API key' => 'የጉግል ኤፒአይ ቁልፍ','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'የጉግል ኤፒአይ ቁልፍዎን ይለጥፉ እና ለዚህ ድር ጣቢያ እንደሚሰራ ለማረጋገጥ የሙከራ አዝራሩን ይጠቀሙ። ቁልፉ የሚሰራ እና ለጎራዎ የተፈቀደ መሆኑን ያረጋግጡ፣ አለበለዚያ የአድራሻ መስኩ ደንበኞች ትዕዛዞቻቸውን እንዳያጠናቅቁ ሊታገድ ይችላል።','Enable Google address autocomplete' => 'የጉግል አድራሻ ራስ-ሰር ማጠናቀቂያን ያንቁ','Enable address autocompletion using the Google Maps APIs.' => 'የGoogle ካርታዎች APIዎችን በመጠቀም የአድራሻ ራስ-ሰር ማጠናቀቅን ያንቁ።','Google API language' => 'የጉግል ኤፒአይ ቋንቋ','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'ይህ ቋንቋ የGoogle Places API አድራሻ ጥቆማዎችን ለማሳየት ጥቅም ላይ ይውላል፣ እና አድራሻዎችም በዚህ ቋንቋ በራስ-ሰር ይሞላሉ።','Result types' => 'የውጤት ዓይነቶች','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ማንኛውንም አይነት ውጤት ለመቀበል ባዶ ይተዉት፣ ይህም ብዙውን ጊዜ የተሻሉ የማዛመጃ ውጤቶችን ይሰጣል። <a href="%s" target="_blank">ለተጨማሪ ዝርዝሮች ሰነዱን ይመልከቱ</a> ።<br> በአድራሻ ራስ-ሰር መሙላት መስኮች ላይ ለመመለስ እስከ 5 የሚደርሱ የአድራሻ ፍለጋ ውጤቶችን ይምረጡ።<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ስለሚደገፉት አይነቶች</a> የበለጠ ለማወቅ የGoogle ካርታዎችን ሰነድ ይጎብኙ።','Result types (Legacy API)' => 'የውጤት ዓይነቶች (ሌጋሲ ኤፒአይ)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'የቦታዎች ኤፒአይ (ሌጋሲ) ሲጠቀሙ ምን አይነት የአድራሻ ፍለጋ ውጤቶች መመለስ አለባቸው።<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">ስለሚደገፉት አይነቶች</a> የበለጠ ለማወቅ የLegacy Google Places API ሰነዶችን ይጎብኙ።','Company fields' => 'የኩባንያ መስኮች','Enable autocomplete for the company name if available' => 'የሚገኝ ከሆነ ለኩባንያው ስም ራስ-አጠናቅቅን ያንቁ','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'ከGoogle Maps APIዎች ሲመለሱ የኩባንያውን ስም መረጃ በመጠቀም የኩባንያውን መስክ በራስ-ሰር ማጠናቀቅን ያንቁ።','Business search' => 'የንግድ ፍለጋ','Enable search for businesses in the company field' => 'በኩባንያው መስክ ውስጥ ንግዶችን መፈለግን ያንቁ','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'በኩባንያው መስክ ውስጥ ሲተይቡ ከንግድ ጋር የተያያዙ የአድራሻዎችን ጥቆማ ያንቁ፣ ከዚያም አንድ ንግድ ከአስተያየቶቹ ውስጥ ሲመረጥ ሁሉንም የአድራሻ መስኮች በራስ-ሰር ያጠናቅቁ።','Company result types' => 'የኩባንያ ውጤት ዓይነቶች','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'በራስ-ሰር የኩባንያ መስኮች ላይ ለመመለስ እስከ 5 የሚደርሱ የአድራሻ ፍለጋ ውጤቶችን ይምረጡ።<br> የሚመከር ዋጋ <code>establishment</code> ነው፣ ይህም አብዛኛዎቹን የንግድ ዓይነቶች ያካትታል።<br> ከንግዶች ጋር ያልተያያዙ ውጤቶችን ጨምሮ ማንኛውንም አይነት ውጤት ለመቀበል ባዶ ይተዉት።<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ስለሚደገፉት አይነቶች</a> የበለጠ ለማወቅ የGoogle ካርታዎችን ሰነድ ይጎብኙ።','Google logo' => 'የጉግል አርማ','Show text and logo "Powered by Google"' => '«በGoogle የተጎላበተ» የሚለውን ጽሑፍ እና አርማ አሳይ','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'ምልክት ሲደረግበት፣ &quot;በGoogle የተጎላበተ&quot; የሚለው ጽሑፍ እና አርማ በአድራሻው ራስ-ሰር ማጠቃለያ የአስተያየት ሳጥን ግርጌ ላይ ይታያል።','Brasil API address autocomplete' => 'የብራዚል ኤፒአይ አድራሻ ራስ-ሰር አጠናቅቅ','Brasil API' => 'የብራዚል ኤፒአይ','Enable Brasil API address autocomplete for CEP fields' => 'ለCEP መስኮች የብራዚል ኤፒአይ አድራሻ ራስ-ማጠናቀቅን ያንቁ','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'የCEP/ፖስትኮድ መስክን በመጠቀም አድራሻዎችን ለማግኘት እና በራስ-ሰር ለመሙላት የብራዚል ኤፒአይ ይጠቀሙ። ለብራዚል አድራሻዎች ብቻ ተገቢ ነው።','API version' => 'የኤፒአይ ስሪት','Choose which version of the Brasil API CEP method to use.' => 'የትኛውን የብራዚል API CEP ዘዴ ስሪት መጠቀም እንዳለቦት ይምረጡ።','Address book migration' => 'የአድራሻ ደብተር ፍልሰት','WooCommerce addresses' => 'የዎኦኮሜርስ አድራሻዎች','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'አሁን ያሉትን የማጓጓዣ እና የክፍያ አድራሻዎችን ከWooCommerce ወደ ደንበኛው የአድራሻ ደብተር ይቅዱ።','Enable the address book feature' => 'የአድራሻ ደብተር ባህሪን ያንቁ','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'ደንበኞች ብዙ አድራሻዎችን እንዲያስቀምጡ እና ለማጓጓዣ እና ለሂሳብ አከፋፈል የሚያገለግል ነባሪ አድራሻ እንዲገልጹ ይፍቀዱላቸው።','Address labels' => 'የአድራሻ መለያዎች','Allow customers to add a custom label for each address' => 'ደንበኞች ለእያንዳንዱ አድራሻ ብጁ መለያ እንዲያክሉ ይፍቀዱላቸው','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'የአድራሻ መለያዎች ደንበኞች የተቀመጡ አድራሻዎቻቸውን (ለምሳሌ፡ &quot;የእናቶች ቤት&quot;) መለየት ቀላል ያደርጉላቸዋል። የአድራሻ መለያዎች ለደንበኞች የግል ናቸው፣ እና በትዕዛዝ ዝርዝሮች ገጽ ወይም በደረሰኞች ላይ አይታዩም ወይም አይታተሙም።','Display layout' => 'የማሳያ አቀማመጥ','Choose how saved addresses are displayed at checkout and on the cart.' => 'የተቀመጡ አድራሻዎች በቼክ መውጫ እና በጋሪው ላይ እንዴት እንደሚታዩ ይምረጡ።','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'በቼክ መውጫ እና በጋሪው ላይ ይተገበራል። በመለያ ገጹ ላይ የተቀመጡ አድራሻዎች ሁልጊዜ የካርዶችን አቀማመጥ ይጠቀማሉ።','Address cards' => 'የአድራሻ ካርዶች','Address list' => 'የአድራሻ ዝርዝር','Dropdown field' => 'የተቆልቋይ መስክ','Address search' => 'የአድራሻ ፍለጋ','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'ደንበኛው ቢያንስ ይህ የተቀመጡ አድራሻዎች ብዛት ሲኖረው በfrontend ላይ የአድራሻ ፍለጋ ማጣሪያን ያሳዩ።','Not used when display layout is set to dropdown field.' => 'የማሳያ አቀማመጥ ወደ ተቆልቋይ መስክ ሲዋቀር ጥቅም ላይ አይውልም።','Addresses' => 'አድራሻዎች','Enable cart page optimizations to see more options' => 'ተጨማሪ አማራጮችን ለማየት የጋሪ ገጽ ማሻሻያን ያንቁ','Sticky order summary' => 'ተለጣፊ የትዕዛዝ ማጠቃለያ','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'በጋሪ ገጹ ላይ የኩፖን ኮዶችን ክፍል የት እንደሚታይ ቦታ ይምረጡ። የAJAX ጋሪ ሲነቃ እና የኩፖን ኮዶች አጠቃቀም በWooCommerce ቅንብሮች ውስጥ ከነቃ ብቻ ተፈጻሚ ይሆናል።','Layout of cross-sell' => 'የመስቀል-ሽያጭ አቀማመጥ','Cross-sells displayed' => 'የተሻገሩ ሽያጭዎች ይታያሉ','Items' => 'እቃዎች','Cart page optimization' => 'የጋሪ ገጽ ማመቻቸት','Give your cart the same clear, conversion-focused layout as your checkout.' => 'ለጋሪዎ ልክ እንደ ቼክአውትዎ ግልጽ፣ ልወጣን ያማከለ አቀማመጥ ይስጡት።','Match the cart layout to the checkout page for a consistent purchase journey.' => 'ወጥ የሆነ የግዢ ጉዞ ለማድረግ የጋሪውን አቀማመጥ ከቼክ መውጫ ገጹ ጋር ያዛምዱት።','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'ጋሪውን ሁልጊዜ ከበስተጀርባ ወቅታዊ ያድርጉት፣ ብዛቶች ሲቀየሩ ሙሉ ገጽ እንደገና መጫን አያስፈልግም።','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'የኩፖን ኮዶችን፣ መላኪያዎችን እና የሽያጭ ኮዶችን በተሻለ ሁኔታ በሚቀይሩበት ቦታ ላይ ያስቀምጡ።','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'የትዕዛዝ ማጠቃለያውን ሲያሸብልሉ እንዲታይ ያድርጉ፣ እና ሸማቾች ማረጋገጫ የሚያስፈልጋቸው የትዕዛዝ ምልክቶችን ያክሉ።','Columns' => 'አምዶች','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'የቼክ መውጫ ደረጃዎች፣ የትዕዛዝ ማጠቃለያ እና ሌሎች ክፍሎች አጠቃላይ ቅጦች። ለሌሎች ቼክ መውጫዎች፣ ጋሪዎች፣ አመሰግናለሁ (ትዕዛዝ ተቀብሏል) እና የትዕዛዝ ገጾችን ይመልከቱ።','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'የ <em>&quot;1 አምድ&quot;</em> አቀማመጥን ከ <em>&quot;Split&quot;</em> የዲዛይን አብነት ጋር ሲጠቀሙ፣ የቀኝ አምድ የሚታየው የገጽ የጎን አሞሌ መግብር አካባቢ ንቁ ከሆነ ብቻ ነው (Checkout Sidebar፣ Cart Sidebar፣ ወይም Order Received Sidebar)። አለበለዚያ ገጹ እንደ Split styles ያለ ነጠላ አምድ ሆኖ ይቆያል።','Split column background' => 'የአምድ ዳራውን ክፈል','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'ለ Split design ሁለተኛ ደረጃ አምድ የጀርባ ቀለም ይምረጡ። የትዕዛዝ ማጠቃለያ ዳራ ቀለምን ለመጠቀም ባዶ ይተዉት።','Page templates' => 'የገጽ አብነቶች','Checkout template' => 'የቼክአውት አብነት','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'በቼክ መውጫ ጊዜ ትኩረትን የሚከፋፍሉ ነገሮችን ለመቀነስ ይመከራል። <a href="https://baymard.com/blog/cart-abandonment" target="_blank">ስለ ጋሪ መተው የተደረገውን ጥናት ያንብቡ</a> ።','Sticky progress bar' => 'ተለጣፊ የሂደት አሞሌ','Progress bar style' => 'የፕሮግረስ ባር ቅጥ','Order totals' => 'የትዕዛዝ ድምር','Background color' => 'የጀርባ ቀለም','Action link' => 'የድርጊት አገናኝ','Mobile order summary' => 'የሞባይል ትዕዛዝ ማጠቃለያ','Mobile initial state' => 'የሞባይል የመጀመሪያ ሁኔታ','Enable editing cart items at checkout' => 'በቼክ መውጫ ላይ የጋሪ እቃዎችን ማርትዕ ያንቁ','Allow customers to change product quantities or remove items directly at the checkout page.' => 'ደንበኞች የምርት መጠኖችን እንዲቀይሩ ወይም እቃዎችን በቀጥታ በቼክ መውጫ ገጹ ላይ እንዲያስወግዱ ይፍቀዱላቸው።','Cart item errors' => 'የጋሪ ንጥል ስህተቶች','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'የኩፖን ኮድ በቼክ መውጫ ወይም በጋሪ ገጾች ላይ እንደ የተለየ ክፍል ሲታይ እና የኩፖን ኮዶችን መጠቀም በWooCommerce ቅንብሮች ውስጥ ከነቃ ብቻ ተፈጻሚ ይሆናል።','Coupon codes position' => 'የኩፖን ኮዶች አቀማመጥ','Apply coupon button' => 'የኩፖን አዝራርን ተግብር','Select style of the "apply coupon" button.' => 'የ&quot;ተግብር ኩፖን&quot; አዝራርን ቅጥ ይምረጡ።','Address line 2' => 'የአድራሻ መስመር 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'ይህ ቅንብር በቼክአውት እና በአካባቢያዊ ፒክአፕ ክፍሎች መካከል የተጋራ ነው። በአካባቢያዊ ፒክአፕ ክፍል ላይ፣ የመርከብ/ፒክአፕ መራጩ በማጓጓዣ ዘዴ ክፍል ውስጥ (ከአድራሻው በፊት) ወይም እንደ የተለየ ክፍል (ከዚያ በኋላ) እንደሚታይ ይወስናል።','Customer accounts' => 'የደንበኛ መለያዎች','Guest checkout' => 'የእንግዳ ክፍያ','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'ከWooCommerce Accounts ቅንብሮች ገጽ የእንግዳ መክፈያ፣ የመግቢያ እና የመለያ መፍጠሪያ አማራጮች። እዚህ ለእርስዎ ምቾት ሲባል የሚተዳደሩ ናቸው፣ ስለዚህ በቅንብሮች መገለጫ የተለያዩ እሴቶችን መጠቀም ይችላሉ።','Allow customers to checkout without an account' => 'ደንበኞች ያለ መለያ እንዲከፍሉ ይፍቀዱላቸው','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'ደንበኞች በቼክ መውጫ ጊዜ መለያ እንዲፈጥሩ ወይም እንዲገቡ እንዳይጠየቁ <strong>ይመከራል</strong> ፣ ይህም የልወጣ ተመኖችን ሊቀንስ ይችላል።','When disabled, customers must log in or create an account to complete the purchase.' => 'ሲሰናከል ደንበኞች ግዢውን ለማጠናቀቅ መግባት ወይም መለያ መፍጠር አለባቸው።','Login at checkout' => 'በክፍያ ቦታ ይግቡ','Enable log-in during checkout' => 'በክፍያ ወቅት መግባትን ያንቁ','Show a link for returning customers to log in from the checkout page.' => 'ተመላሽ ደንበኞች ከቼክ መውጫ ገጹ እንዲገቡ የሚወስድ አገናኝ አሳይ።','Account creation' => 'የመለያ ፈጠራ','Allow customers to create an account during checkout' => 'ደንበኞች በክፍያ ወቅት መለያ እንዲፈጥሩ ይፍቀዱላቸው','Customers can create an account before placing their order.' => 'ደንበኞች ትዕዛዛቸውን ከማስገባታቸው በፊት መለያ መፍጠር ይችላሉ።','Allow customers to create an account from the My account page' => 'ደንበኞች ከኔ መለያ ገጽ መለያ እንዲፈጥሩ ይፍቀዱላቸው','Customers can register a new account from the My account page.' => 'ደንበኞች ከኔ መለያ ገጽ አዲስ መለያ መመዝገብ ይችላሉ።','Username' => 'የተጠቃሚ ስም','Generate from customer\'s name' => 'ከደንበኛ ስም ይፍጠሩ','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'ደንበኞች በቼክ መውጫ ጊዜ የተጠቃሚ ስም እንዳይመርጡ <strong>ይመከራል</strong> ፣ ይህም የልወጣ ተመኖችን ሊቀንስ ይችላል።','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'የተጠቃሚ ስም የሚመነጨው ከደንበኛ ስም ወይም ስም መጠቀም በማይቻልበት ጊዜ ከኢሜይል አድራሻ ነው።','Password' => 'የይለፍ ቃል','Send password setup link' => 'የይለፍ ቃል ማዋቀሪያ አገናኝ ይላኩ','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'ደንበኞች በቼክ መውጫ ጊዜ የይለፍ ቃል እንዲያዘጋጁ እንዳይጠየቁ <strong>ይመከራል</strong> ፣ ይህም የልወጣ ተመኖችን ሊቀንስ ይችላል።','Customers receive an email to create their password securely.' => 'ደንበኞች የይለፍ ቃላቸውን ደህንነቱ በተጠበቀ ሁኔታ ለመፍጠር ኢሜይል ይደርሳቸዋል።','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'የተመዘገቡ ደንበኞች ሳይገቡ ክፍያውን እንዲያጠናቅቁ ይፍቀዱላቸው እና የእውቂያ ዝርዝሮች ሲዛመዱ ትዕዛዙን ከነባር መለያቸው ጋር ያዛምዱ።','Existing account message' => 'አሁን ያለ የመለያ መልእክት','Let customers create an account after placing their order, from the thank you page.' => 'ደንበኞች ትዕዛዝ ከሰጡ በኋላ ከምስጋና ገጹ ላይ መለያ እንዲፈጥሩ ይፍቀዱላቸው።','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'በዚህ ክፍል ውስጥ ያሉ አማራጮች የእንግዳ ክፍያ ሲፈጽሙ እና የመለያ ማመሳሰል ሲነቁ ይገኛሉ። የዘገየ የመለያ መፍጠርን ለማዋቀር ከላይ ያሉትን ሁለቱንም ባህሪያት ያንቁ።','Enable delayed account creation' => 'የዘገየ የመለያ መፍጠርን ያንቁ','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'የእንግዳ ክፍያ እና የመለያ ማመሳሰል ሲነቁ የዘገየ የመለያ መፍጠርን ያንቁ።','Section position' => 'የክፍል አቀማመጥ','Before customer details section' => 'የደንበኛ ዝርዝሮች ክፍል ከመድረሱ በፊት','After customer details section' => 'የደንበኛ ዝርዝሮች ክፍል በኋላ','Account creation benefits' => 'የመለያ መፍጠር ጥቅሞች','Leaving the field empty will display the default text.' => 'መስኩን ባዶ መተው ነባሪውን ጽሑፍ ያሳያል።','Inline buttons' => 'የመስመር ውስጥ አዝራሮች','Required fields' => 'የሚያስፈልጉ መስኮች','Enable gift message fields at checkout' => 'በቼክ መውጫ ላይ የስጦታ መልእክት መስኮችን ያንቁ','Expanded gift message' => 'የተዘረጋ የስጦታ መልእክት','Display gift message field always expanded' => 'የስጦታ መልእክት መስክ ሁልጊዜ ተዘርግቷል','Gift message in order details' => 'የስጦታ መልእክት በቅደም ተከተል ዝርዝሮች','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'በዚህ ክፍል በአሁኑ ጊዜ ምንም ውህደቶች የሉም። ከእያንዳንዱ ተሰኪ እና ገጽታ ጋር የተያያዙ አማራጮች እዚህ የሚታዩት ያ ተሰኪ ወይም ገጽታ ሲነቃ ብቻ ነው።','Phone fields' => 'የስልክ መስኮች','Field visibility' => 'የመስክ ታይነት','Field position' => 'የመስክ አቀማመጥ','Phone country code & validation' => 'የስልክ ሀገር ኮድ እና ማረጋገጫ','Country' => 'አገር','Enable country on phone fields' => 'በስልክ መስኮች ላይ አገርን አንቃ','Filter countries for shipping or billing' => 'አገሮችን ለመላክ ወይም ለክፍያ አጣራ','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'በእያንዳንዱ የስልክ መስክ ላይ ያለውን የአገር መራጭ በሱቅዎ ላይ ለመላክ ወይም ለክፍያ ለተፈቀደላቸው አገሮች ብቻ ይገድቡ።','Validation' => 'ማረጋገጫ','Enable simple validation based on country rules' => 'በአገር ደንቦች ላይ በመመስረት ቀላል ማረጋገጫን ያንቁ','Checks that the phone number is valid for the selected country, including country code and length.' => 'የስልክ ቁጥሩ ለተመረጠው አገር የሚሰራ መሆኑን ያረጋግጣል፣ ይህም የአገር ኮድ እና ርዝመትን ያካትታል።','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'ቁጥሩ ለተመረጠው አገር ትክክለኛ የሞባይል፣ የቋሚ መስመር ወይም ሌላ ተቀባይነት ያለው አይነት መሆኑን በጥብቅ ያረጋግጡ። አንዳንድ ትክክለኛ ቁጥሮችን ውድቅ ሊያደርግ ይችላል።','Validation types' => 'የማረጋገጫ ዓይነቶች','Placeholders' => 'ቦታ ያዢዎች','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'በአሁኑ ጊዜ ለማስተዳደር ምንም የፈቃድ ቁልፎች የሉም። ፈቃድ ያለው የFluid Checkout ተሰኪ ወይም ተጨማሪ ሲነቃ የፈቃድ ቁልፎች እዚህ ይታያሉ።','Default delivery type' => 'ነባሪ የማድረሻ አይነት','Choose which delivery type will be selected by default.' => 'በነባሪነት የትኛው የማድረሻ አይነት እንደሚመረጥ ይምረጡ።','Shipping zone fields' => 'የማጓጓዣ ዞን መስኮች','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'ለአካባቢያዊ የመውሰጃ ዞን የማጣሪያ መስኮች የትኞቹ መስኮች እንደሚታዩ ይምረጡ። ሁሉንም የሚገኙ አማራጮች ለማሳየት ባዶውን ይተዉት።','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'እነዚህ መስኮች ለአካባቢያዊ የመውሰጃ መላኪያ ዘዴዎች ማጣሪያ ሆነው ይታያሉ። አንዳንድ መስኮች እዚህ ካልተመረጡ አሁንም በቼክ መውጫ ላይ ሊታዩ ይችላሉ፣ ተኳሃኝ ተሰኪዎች በትክክል እንዲሰሩ የሚያስፈልጋቸው ከሆነ።','Order shipping address' => 'የማዘዣ መላኪያ አድራሻ','Order pay page optimization' => 'የክፍያ ገጽ ማመቻቸትን ይዘዙ','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'ያልተከፈሉ ትዕዛዞችን ልክ እንደ ቼክአውት ተመሳሳይ ግልጽ፣ ልወጣን ያተኮሩ አቀማመጦችን ይስጡ።','Optimize the layout of the order pay page for orders pending payment.' => 'የክፍያ ጊዜን ለሚጠብቁ ትዕዛዞች የትዕዛዝ ክፍያ ገጽን አቀማመጥ ያሻሽሉ።','Match the order pay experience to your checkout for a consistent purchase journey.' => 'ወጥ የሆነ የግዢ ጉዞ ለማድረግ የትዕዛዝ ክፍያ ልምድን ከቼክ መውጫዎ ጋር ያዛምዱ።','Add trust symbols and badges where shoppers need reassurance before paying.' => 'ሸማቾች ከመክፈልዎ በፊት ማረጋገጫ የሚያስፈልጋቸው የትዕዛዝ ምልክቶችን እና ባጆችን ያክሉ።','Thank you page optimization' => 'የገጽ ማመቻቸትን አመሰግናለሁ','Make the thank you page and order details clearer for customers after they buy.' => 'ደንበኞች ከገዙ በኋላ የምስጋና ገጹን እና የትዕዛዝ ዝርዝሮቹን ለደንበኞች ግልጽ ያድርጉት።','Optimize the thank you page and account order details with a clearer layout.' => 'የምስጋና ገጽን እና የመለያ ትዕዛዝ ዝርዝሮችን የበለጠ ግልጽ በሆነ አቀማመጥ ያሻሽሉ።','Show order status progress, actions, downloads, and notes where they make sense.' => 'የትዕዛዝ ሁኔታ ሂደትን፣ እርምጃዎችን፣ ውርዶችን እና ማስታወሻዎችን ትርጉም በሚሰጡበት ቦታ ያሳዩ።','Customize order details sections on email notifications.' => 'የትዕዛዝ ዝርዝሮች ክፍሎችን በኢሜይል ማሳወቂያዎች ላይ ያብጁ።','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'ሸማቾች ከገዙ በኋላ ማረጋገጫ የሚያስፈልጋቸው የትዕዛዝ ምልክቶችን እና ባጆችን ያክሉ።','Email notifications' => 'የኢሜይል ማሳወቂያዎች','Enable thank you page and order details optimizations to see more options' => 'ተጨማሪ አማራጮችን ለማየት የምስጋና ገጽን እና የትዕዛዝ ዝርዝሮችን ማመቻቸት ያንቁ','Use wide layout on thank you page' => 'በምስጋና ገጽ ላይ ሰፊ አቀማመጥ ይጠቀሙ','These options affect the thank you page, view order details on account pages and on email notifications.' => 'እነዚህ አማራጮች የምስጋና ገጹን ይነካሉ፣ የትዕዛዝ ዝርዝሮችን በመለያ ገጾች ላይ እና በኢሜይል ማሳወቂያዎች ላይ ይመልከቱ።','Save settings' => 'ቅንብሮችን አስቀምጥ','Docs' => 'ሰነዶች','Cart' => 'ጋሪ','Thank you' => 'አመሰግናለሁ','Address autocomplete' => 'የአድራሻ ራስ-ሰር አጠናቅቅ','Trust badges' => 'የእምነት ባጆች','You do not have permission to save these settings.' => 'እነዚህን ቅንብሮች ለማስቀመጥ ፈቃድ የለህም።','Invalid save request.' => 'ልክ ያልሆነ የማስቀመጫ ጥያቄ።','Your settings have been saved.' => 'ቅንብሮችዎ ተቀምጠዋል።','Saving...' => 'በማስቀመጥ ላይ...','Settings could not be saved. Please try again.' => 'ቅንብሮች ሊቀመጡ አልቻሉም። እባክዎ እንደገና ይሞክሩ።','Dismiss notice' => 'ማስታወቂያውን ውድቅ አድርግ','Open settings menu' => 'የቅንብሮች ምናሌን ክፈት','Close settings menu' => 'የቅንብሮች ምናሌን ዝጋ','Preview' => 'ቅድመ እይታ','Expand preview' => 'ቅድመ እይታን ዘርጋ','Collapse preview' => 'ቅድመ እይታን ሰብስብ','Show header and footer' => 'ራስጌ እና ግርጌ አሳይ','Hide header and footer' => 'ራስጌ እና ግርጌን ደብቅ','Page preview' => 'የገጽ ቅድመ እይታ','Preview viewport' => 'የእይታ ጣቢያን አስቀድመው ይመልከቱ','Tablet' => 'ጡባዊ','Desktop' => 'ዴስክቶፕ','Preview width' => 'የቅድመ እይታ ስፋት','Decrease width' => 'ስፋትን ቀንስ','Preview width in pixels' => 'ስፋትን በፒክሰሎች አስቀድመው ይመልከቱ','Increase width' => 'ስፋት ጨምር','Preview as' => 'ቅድመ እይታ እንደ','Guest' => 'እንግዳ','Logged in' => 'ገብተዋል','Preview page' => 'ቅድመ እይታ ገጽ','Expand preview for a closer look' => 'በቅርበት ለማየት ቅድመ እይታን ዘርጋ','Available with %s.' => 'ከ%s ጋር ይገኛል።','Turn them on' => 'ያብሩዋቸው','Optimizations for this page are turned off. %s to preview the page.' => 'የዚህ ገጽ ማመቻቸት ጠፍቷል። ገጹን ለማየት %s።','%s preview' => 'የ%s ቅድመ እይታ','Isolated session · nothing is saved' => 'የተገለለ ክፍለ ጊዜ · ምንም አልተቀመጠም','Usage tracking' => 'የአጠቃቀም ክትትል','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Fluid Checkout ተኳሃኝነትን ለማሻሻል የሚረዱ ስሜታዊ ያልሆኑ የጣቢያ አካባቢ ሪፖርቶችን ይላኩ። ሪፖርቶች ከታች ባሉት አማራጮች ውስጥ እስኪነቁ ድረስ አይላኩም።','Send usage tracking reports to Fluid Checkout' => 'የአጠቃቀም መከታተያ ሪፖርቶችን ወደ Fluid Checkout ይላኩ','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'እነዚህ ሪፖርቶች ለጣቢያዎ ተኳሃኝነትን እና ድጋፍን ለማሻሻል ይረዱናል እና ሲነቁ በየሳምንቱ ይላካሉ።','No customer, admin user, or any other sensitive data is included in the reports.' => 'በሪፖርቶቹ ውስጥ ምንም ደንበኛ፣ የአስተዳዳሪ ተጠቃሚ ወይም ሌላ ሚስጥራዊ መረጃ አልተካተተም።','Basic environment info' => 'መሰረታዊ የአካባቢ መረጃ','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'የዎርድፕረስ፣ የPHP፣ የWooCommerce፣ የገጽታ እና የፕለጊን ዝርዝር ውሂብ። ሪፖርት ማድረግ ሲነቃ ሁልጊዜ ይካተታል። ጣቢያዎ እየሰራ መሆኑን እንድንረዳ ያግዘናል።','Plugin settings' => 'የተሰኪ ቅንብሮች','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'የድጋፍ ጥያቄዎችን ለማገዝ የFluid Checkout ተሰኪ ቅንብሮችን ይልካል እና ተሰኪዎቻችንን እንዴት እየተጠቀሙ እንደሆነ እንድንረዳ ያግዘናል።','Coming soon' => 'በቅርቡ ይመጣል','Sales metrics' => 'የሽያጭ መለኪያዎች','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'እስከ ዛሬ ድረስ የፈሉይድ ቼክአውት ከመጫንዎ በፊት ወርሃዊ የትዕዛዝ ብዛት እና አጠቃላይ ሽያጮች። ተሰኪዎቻችንን በመጫን ተጨማሪ ገንዘብ እያገኙ እንደሆነ ለመረዳት ይረዳናል። ምንም የደንበኛ ወይም የተጠቃሚ መረጃ አይላክም።','Utilities' => 'መገልገያዎች','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'ከ <code>select2</code> ይልቅ <code>TomSelect</code> ተቆልቋይ ክፍሎችን ይጠቀሙ','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect ከ Select2 ጋር ሲነጻጸር ለስህተት የመጋለጥ እድሉ አነስተኛ የሆነ ቀላል የተቆልቋይ ምርጫ አካል ሲሆን ተመሳሳይ ተግባርም ይሰጣል።','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'በትናንሽ መሳሪያዎች ላይ ከቅጽ መስኮች ጋር ሲገናኙ በራስ-ሰር ማጉላትን ለማስወገድ በዚህ ተሰኪ በተመቻቹ ገጾች ላይ የቅርጸ-ቁምፊውን መጠን ወደ 16 ፒክስል ያዘጋጃል።','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'የፋየርፎክስ መጠኑ ከ16 ፒክስል በታች ሲሆን ጽሑፉ ለማንበብ ቀላል እንዲሆን ሳፋሪ እና ሌሎች አሳሾች በሞባይል መሳሪያዎች ላይ በራስ-ሰር ሊያጉሉ ይችላሉ።','Enable script processing tracking on the browser console.' => 'በአሳሽ ኮንሶል ላይ የስክሪፕት ሂደት ክትትልን ያንቁ።','Unminified assets' => 'ያልተገደቡ ንብረቶች','Google Maps scripts' => 'የጉግል ካርታዎች ስክሪፕቶች','Do not remove duplicate Google Maps scripts' => 'የተባዙ የGoogle ካርታዎች ስክሪፕቶችን አያስወግዱ','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'ሲነቃ፣ የተባዙ የGoogle ካርታዎች ስክሪፕቶች አይወገዱም፣ ይህም ስህተቶችን እና የአፈጻጸም ችግሮችን ሊያስከትል ይችላል። መላ ፍለጋ ሲያደርጉ ብቻ ይህንን አማራጭ ይጠቀሙ።','Widget areas' => 'የመግብር ቦታዎች','Last step on mobile' => 'በሞባይል ላይ የመጨረሻው እርምጃ','Display widgets only at last step on mobile' => 'መግብሮችን በሞባይል ላይ በመጨረሻው ደረጃ ላይ ብቻ ያሳዩ','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'የመጨረሻውን የቼክ መውጫ ደረጃ በሞባይል መሳሪያዎች ላይ ሲመለከቱ ብቻ የቼክ መውጫ የትረስት ባጅ መግብሮችን ያሳዩ','Standard' => 'መደበኛ','VAT number field' => 'የቫት ቁጥር መስክ','Add a VAT number field to the billing form.' => 'የቫት ቁጥር መስክ ወደ የክፍያ መጠየቂያ ቅጹ ያክሉ።','Field label' => 'የመስክ መለያ','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'የቫት ቁጥር መስኩን መለያ (ማለትም የቫት ቁጥር) ያዘጋጁ። በብዙ ቋንቋዎች በሚዘጋጁ ድር ጣቢያዎች ላይ፣ ይህንን መስክ ባዶ መተው እና የመጀመሪያውን ሕብረቁምፊ መተርጎም የተሻለ ነው።','VAT Number' => 'የቫት ቁጥር','EU-VAT' => 'የአውሮፓ ህብረት-ቫት','Enable the VAT number field to see more options' => 'ተጨማሪ አማራጮችን ለማየት የቫት ቁጥር መስኩን ያንቁ','VAT validation' => 'የቫት ማረጋገጫ','Validate VAT number field for EU-VAT during checkout' => 'በክፍያ ወቅት የአውሮፓ ህብረት-ቫት የቫት ቁጥር መስክን ያረጋግጡ','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'የተሰጠው የቫት ቁጥር በአውሮፓ VIES የውሂብ ጎታ (የቫት መረጃ ልውውጥ ስርዓት) ላይ የተመዘገበ ትክክለኛ የቫት ቁጥር መሆኑን ያረጋግጣል።','Shop VAT number' => 'የተጨማሪ እሴት ታክስ ቁጥር ይግዙ','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'የሱቁ የቫት ቁጥር የአውሮፓ ህብረት-ቫት ማረጋገጫ ለመጠየቅ ጥቅም ላይ የዋለ ሲሆን በደረሰኞች ላይ የታተመ ነው።<br> የ VIES ምክክር ውጤቶች ለሂሳብ አያያዝ አገልግሎት ላይሆኑ ስለሚችሉ <strong>የሱቅ ቫት ቁጥርዎን እንዲያክሉ አጥብቀን እንመክራለን</strong> ።<br> ማለትም <code>ATU99999999</code> ወይም <code>EE999999999</code>','Reverse charge' => 'የተገላቢጦሽ ክፍያ','Apply reverse charge mechanism' => 'የተገላቢጦሽ ክፍያ ዘዴን ይተግብሩ','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'የግብር ተመኑን ወደ ዜሮ ያቀናብሩ እና የደንበኛው የቫት ቁጥር የሚሰራ ሲሆን በደረሰኞች ላይ &quot;የተገላቢጦሽ ክፍያ&quot; ያሳዩ። እንደ መደብሩ ሀገር የተለየ &quot;የተገላቢጦሽ ክፍያ&quot; ጽሑፍ ሊያስፈልግ ይችላል።','Same country' => 'ተመሳሳይ ሀገር','Apply reverse charge mechanism for transactions in the shop country:' => 'በሱቅ ሀገር ውስጥ ለሚደረጉ ግብይቶች የተገላቢጦሽ ክፍያ ዘዴን ይተግብሩ፡','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'በሱቁ ውስጥ በተመሳሳይ ሀገር ውስጥ ባሉ ኩባንያዎች መካከል ለሚደረጉ ግብይቶች የተገላቢጦሽ ክፍያ ዘዴን መተግበር ያስችላል።','Reverse charge exceptions' => 'የተገላቢጦሽ ክፍያ ልዩ ሁኔታዎች','Select additional countries to skip applying the reverse charge mechanism.' => 'የተገላቢጦሽ ክፍያ ዘዴን ተግባራዊ ለማድረግ ተጨማሪ አገሮችን ይምረጡ።','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'ትክክለኛ የቫት ቁጥር ቢሰጥም እንኳ ከእነዚህ አገሮች ለሚመጡ ትዕዛዞች ግብር ይከፍላል።','Reverse charge label on invoices' => 'በደረሰኞች ላይ የተገላቢጦሽ የክፍያ መለያ','Set the label of "reverse charge" on the checkout page and order details.' => 'በቼክ መውጫ ገጹ ላይ &quot;የተገላቢጦሽ ክፍያ&quot; የሚለውን መለያ እና የትዕዛዝ ዝርዝሮችን ያዘጋጁ።','Reverse charge text on invoices' => 'በደረሰኞች ላይ የተገላቢጦሽ የክፍያ ጽሑፍ','Set the label of "reverse charge" text on invoices.' => 'በደረሰኞች ላይ &quot;የተገላቢጦሽ ክፍያ&quot; የሚለውን መለያ ያዘጋጁ።','Tax to be paid on reverse charge basis' => 'በተገላቢጦሽ ክፍያ መሰረት የሚከፈል ግብር','Company name' => 'የኩባንያ ስም','Autocomplete company name from VAT number' => 'የኩባንያ ስም ከቫት ቁጥር በራስ-ሰር ያጠናቅቁ','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'ደንበኛው በሰጠው ትክክለኛ የቫት ቁጥር ላይ በመመስረት የክፍያ ኩባንያውን ስም ይሙሉ።','Company name editing' => 'የኩባንያ ስም አርትዖት','Allow editing of auto-filled company name' => 'በራስ-ሰር የተሞላ የኩባንያ ስም አርትዖት ይፍቀዱ','When enabled, customers can change the company name associated with the provided VAT number.' => 'ሲነቃ፣ ደንበኞች ከተሰጠው የቫት ቁጥር ጋር የተያያዘውን የኩባንያ ስም መቀየር ይችላሉ።','EU-VAT for digital goods' => 'ለዲጂታል እቃዎች የአውሮፓ ህብረት-ቫት','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'ከጃንዋሪ 1፣ 2015 ጀምሮ፣ ዲጂታል እቃዎችን በተመለከተ በአውሮፓ ህብረት የቫት ደንቦች ላይ ማሻሻያዎች ተደርገዋል፣ ይህም የB2C ግብይቶችን ብቻ ይነካል፡፡ በዲጂታል እቃዎች ላይ ያለው የቫት መጠን በደንበኛው ቦታ ላይ ተመስርቶ መሰላ አለበት፣ እናም የዚህ ማስረጃ መሰብሰብ አለበት (የአይፒ አድራሻ እና የክፍያ አድራሻ)።','Tax classes for digital goods' => 'ለዲጂታል እቃዎች የግብር ክፍሎች','Select some tax classes' => 'አንዳንድ የግብር ክፍሎችን ይምረጡ','Location evidence' => 'የአካባቢ ማስረጃ','Collect customer\'s location evidence' => 'የደንበኛውን የአካባቢ ማስረጃ ይሰብስቡ','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'የአይፒ አድራሻውን ያስቀምጣል እና ከደንበኛው የክፍያ አድራሻ ጋር በማነፃፀር ያረጋግጣል። ደንበኛው ከክፍያ አድራሻው እና ከአይፒ አድራሻው ጋር የማይዛመዱ ከሆነ በቼክ መውጫ ገጹ ላይ ባለው የአመልካች ሳጥን ላይ ምልክት በማድረግ የክፍያ አድራሻቸውን ማረጋገጥ አለባቸው።','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'ይህ አማራጭ በፈሉድ Checkout ውስጥ የሚተዳደር ነው። <a href="%s">በደንበኛ መለያዎች ቅንብሮች ውስጥ ይቀይሩት</a> ።','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'ይህ አማራጭ በፈሉድ ቼክአውት ውስጥ የሚተዳደር ነው። በፈሉድ ቼክአውት &gt; የደንበኛ መለያዎች ስር ይቀይሩት።','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'ይህ አማራጭ በFluid Checkout ውስጥ የሚተዳደር ነው። የFluid Checkout ሲነቃ የመላኪያ መድረሻው ሁልጊዜ &quot;ወደ ደንበኛ መላኪያ አድራሻ ነባሪ&quot; ተብሎ ይቀናበራል። ደንበኞች በቼክ መውጫ ጊዜ የተለያዩ የመላኪያ እና የክፍያ አድራሻዎችን ማቅረብ ይችላሉ።<br><br> ነባሪውን የክፍያ አድራሻ ከማጓጓዣ አድራሻው ጋር ተመሳሳይ እንዲሆን ለማድረግ የሚያስችል አማራጭ በ <a href="%s">Fluid Checkout ቅንብሮች</a> ውስጥ ይገኛል።','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'ይህ አማራጭ በFluid Checkout ውስጥ የሚተዳደር ነው። የFluid Checkout ሲነቃ የመላኪያ መድረሻው ሁልጊዜ &quot;ወደ ደንበኛ መላኪያ አድራሻ ነባሪ&quot; ተብሎ ይቀናበራል። ደንበኞች በቼክ መውጫ ጊዜ የተለያዩ የመላኪያ እና የክፍያ አድራሻዎችን ማቅረብ ይችላሉ።<br><br> ነባሪውን የክፍያ አድራሻ ከማጓጓዣ አድራሻው ጋር ተመሳሳይ እንዲሆን ለማድረግ የሚያስችል አማራጭ በWooCommerce &gt; Settings &gt; Fluid Checkout ላይ ይገኛል።','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'እነዚህ ቅንብሮች ወደ WP Admin &gt; Fluid Checkout &gt; ቅንብሮች ተወስደዋል።','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'ይህ የWooCommerce ቅንብሮች ትር ተቋርጧል እና በFluid Checkout 6.0 ውስጥ ይወገዳል።','Go to settings page' => 'ወደ ቅንብሮች ገጽ ይሂዱ','Hide this tab permanently' => 'ይህንን ትር ለዘላለም ደብቅ','Site report preview' => 'የጣቢያ ሪፖርት ቅድመ እይታ','This is the data that would be included in the next site environment report based on your current settings.' => 'ይህ በአሁኑ ቅንብሮችዎ ላይ በመመስረት በሚቀጥለው የጣቢያ አካባቢ ሪፖርት ውስጥ የሚካተተው ውሂብ ነው።','Loading report preview...' => 'የሪፖርት ቅድመ እይታ በመጫን ላይ...','Could not load the site report preview. Try again.' => 'የጣቢያ ሪፖርት ቅድመ እይታውን መጫን አልተቻለም። እንደገና ይሞክሩ።','Could not send the site report. Try again.' => 'የጣቢያውን ሪፖርት መላክ አልተቻለም። እንደገና ይሞክሩ።','Site report sent successfully.' => 'የጣቢያ ሪፖርት በተሳካ ሁኔታ ተልኳል።','Enable and send now' => 'አንቃ እና አሁኑኑ ላክ','Close' => 'ገጠመ','A site report request is already in progress. Try again in a moment.' => 'የጣቢያ ሪፖርት ጥያቄ አስቀድሞ በሂደት ላይ ነው። ከጥቂት ጊዜ በኋላ እንደገና ይሞክሩ።','Site environment reporting is disabled.' => 'የጣቢያ አካባቢ ሪፖርት ማድረግ ተሰናክሏል።','No site report data is available to send.' => 'ለመላክ ምንም የጣቢያ ሪፖርት ውሂብ የለም።','This site domain cannot send environment reports (local or development domains are excluded).' => 'ይህ የጣቢያ ጎራ የአካባቢ ሪፖርቶችን መላክ አይችልም (አካባቢያዊ ወይም የልማት ጎራዎች አልተካተቱም)።','A site report was sent recently. Try again later.' => 'የጣቢያ ሪፖርት በቅርቡ ተልኳል። ቆይተው እንደገና ይሞክሩ።','The site report could not be sent. Try again later.' => 'የጣቢያው ሪፖርት ሊላክ አልቻለም። ቆይተው እንደገና ይሞክሩ።','Site environment reporting is not available.' => 'የጣቢያ አካባቢ ሪፖርት ማድረግ አይገኝም።','No site report data is available for the selected settings.' => 'ለተመረጡት ቅንብሮች ምንም የጣቢያ ሪፖርት ውሂብ የለም።','You are not allowed to manage site reports.' => 'የጣቢያ ሪፖርቶችን ማስተዳደር አይፈቀድልዎትም።','PRO feature' => 'የፕሮ ባህሪ','Other plugins' => 'ሌሎች ተሰኪዎች','Get only this add-on &mdash; %s' => 'ይህንን ተጨማሪ ብቻ ያግኙ — %s','Install add-on' => 'ተጨማሪውን ይጫኑ','Upgrade to PRO &mdash; %s' => 'ወደ PRO ያሻሽሉ — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'እነዚህን አማራጮች ለመክፈት <a target="_blank" href="%1$s">%2$s ያግኙ</a> ።','Add-on' => 'ተጨማሪ','View documentation' => 'ሰነዶችን ይመልከቱ','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'ጥያቄዎች የገባ የዎርድፕረስ ተጠቃሚ ያስፈልጋቸዋል። የተጠቃሚ_መታወቂያ የአሁኑን ተጠቃሚ ውሂብ እንዳይጠቀም ይተዉት፣ ወይም ደዋዩ ያንን ተጠቃሚ ማርትዕ ሲችል የተጠቃሚ_መታወቂያውን ለሌላ መለያ ኢላማ ለማድረግ ያልፉ (የተጠቃሚ_ማስተካከያ ችሎታ)። ያልተረጋገጡ ጥያቄዎች fc_api_forbidden ይመልሳሉ። ልክ ያልሆነ የተጠቃሚ_መታወቂያ fc_api_user_not_foundን ይመልሳል።','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 ከ { &quot;data&quot;: { ... } } ጋር ተቆጣጣሪው የክፍያ ጭነት ሲመልስ።','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 ከ { &quot;success&quot;: true } ጋር የክፍያ ጭነት በማይኖርበት ጊዜ (ለምሳሌ DELETE)።','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'ውድቀቶች የWordPress REST ስህተት JSONን ከWP_Error ይመልሳሉ (ኮድ፣ መልእክት፣ data.status)። የሽቦ ኮዶች የfc_api_* ቅድመ ቅጥያ ይጠቀማሉ።','Forbidden access.' => 'የተከለከለ መዳረሻ።','Target user was not found.' => 'የታለመው ተጠቃሚ አልተገኘም።','This feature is not available.' => 'ይህ ባህሪ አይገኝም።','A required address field is missing.' => 'የሚያስፈልግ የአድራሻ መስክ ጠፍቷል።','Postcode or ZIP is invalid.' => 'የፖስታ ኮድ ወይም ዚፕ ኮድ ልክ አይደለም።','Phone number is invalid.' => 'የስልክ ቁጥሩ ልክ አይደለም።','State or county is invalid.' => 'ክፍለ ሀገር ወይም አውራጃ ልክ አይደለም።','Country is invalid or has no address fields.' => 'አገሩ ልክ ያልሆነ ነው ወይም የአድራሻ መስኮች የሉትም።','The request could not be processed.' => 'ጥያቄው ሊካሄድ አልቻለም።','Back to previous step' => 'ወደ ቀዳሚው ደረጃ ተመለስ','Skip to settings' => 'ወደ ቅንብሮች ዝለል','Start over and return to the first guided setup step' => 'እንደገና ይጀምሩ እና ወደ መጀመሪያው የሚመራ የማዋቀሪያ ደረጃ ይመለሱ','Start over' => 'እንደገና ጀምር','Please complete all sub-steps before continuing.' => 'ከመቀጠልዎ በፊት እባክዎ ሁሉንም ንዑስ ደረጃዎች ያጠናቅቁ።','Expand' => 'ዘርጋ','Collapse' => 'ሰብስብ','Skip' => 'ዝለል','Mark as complete' => 'እንደ ሙሉ ምልክት አድርግበት','Mark as incomplete' => 'ያልተሟላ እንደሆነ ምልክት አድርግበት','View full-size image: %s' => 'ሙሉ መጠን ያለው ምስል ይመልከቱ፡ %s','Full-size setup guide image' => 'የሙሉ መጠን ቅንብር መመሪያ ምስል','Close image' => 'ምስሉን ዝጋ','Fluid Checkout Guided Setup' => 'የፈሉድ ቼክአውት የሚመራ ማዋቀር','Welcome' => 'እንኳን ደህና መጣህ','Explore your checkout' => 'የክፍያ ክፍያዎን ያስሱ','All set' => 'ሁሉም ተዘጋጅቷል','You do not have permission to access this page.' => 'ወደዚህ ገጽ የመድረስ ፈቃድ የለዎትም።','Go to step %1$d: %2$s' => 'ወደ ደረጃ %1$d ይሂዱ: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'ይህ የሚመራ ቅንብር ከFluid Checkout ጋር እንዲተዋወቁ ይረዳዎታል። ከዚህ በታች ያሉት ደረጃዎች ለጊዜው የቦታ መያዣዎች ናቸው።','Continue to the next step when you are ready.' => 'ዝግጁ ሲሆኑ ወደሚቀጥለው ደረጃ ይቀጥሉ።','Open your store checkout to see Fluid Checkout in action.' => 'የፍሎይድ ቼክአውት በተግባር ላይ ለማየት የሱቅ ቼክአውትዎን ይክፈቱ።','View checkout page' => 'የመክፈያ ገጹን ይመልከቱ','You can return to Fluid Checkout settings to continue configuring your store.' => 'መደብርዎን ማዋቀርዎን ለመቀጠል ወደ Fluid Checkout ቅንብሮች መመለስ ይችላሉ።','Review checkout and cart settings' => 'የክፍያ እና የጋሪ ቅንብሮችን ይገምግሙ','Explore add-ons from the dashboard' => 'ከዳሽቦርዱ ላይ ተጨማሪዎችን ያስሱ','Finish & go to settings' => 'ጨርስ እና ወደ ቅንብሮች ሂድ','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'የክፍያ ስልክ መስክ ታይነት አማራጩን ከዎኦኮሜርስ ኮንቬንሽኖች ጋር እንዲዛመድ ከድሮው እሴት ያዘምኑ።','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'የማጓጓዣ ስልክ መስክ ታይነት አማራጩን ከዎኦኮሜርስ ኮንቬንሽኖች ጋር እንዲዛመድ ከድሮው እሴት ያዘምኑ።','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'የትዕዛዝ ማጠቃለያ ዳራ ቀለም ቅንብሩን ወደ አዲሱ የ Split design ሁለተኛ ደረጃ አምድ ዳራ ቀለም አማራጭ ይቅዱ።','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'የተሻሻለው የምርጫ መስኮች ባህሪ የBiteship ተሰኪውን ሲጠቀሙ ሁልጊዜ ይሰናከላል።','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'የጀርመን ገበያን ሲጠቀሙ የቦታ ትዕዛዝ አቀማመጥ ሁልጊዜ &quot;ከትዕዛዝ ማጠቃለያ በታች&quot; ተብሎ ይቀናበራል። ያ ተሰኪ ከትዕዛዝ ማጠቃለያው በታች የቦታ ትዕዛዝ አዝራር እና ህጋዊ አመልካች ሳጥኖች እንዲታዩ ይፈልጋል።','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'ለWooCommerce ጀርመንኛን ሲጠቀሙ የቦታ ትዕዛዝ አቀማመጥ ሁልጊዜ &quot;ከትዕዛዝ ማጠቃለያ በታች&quot; ተብሎ ይቀናበራል። ያ ተሰኪ ከትዕዛዝ ማጠቃለያው በታች የቦታ ትዕዛዝ አዝራሩን እና ህጋዊ የአመልካች ሳጥኖችን ይፈልጋል።','Edit pickup locations' => 'የመውሰጃ ቦታዎችን ያርትዑ','Use local pickup label from WooCommerce settings' => 'ከWooCommerce ቅንብሮች የአካባቢውን የመውሰጃ መለያ ይጠቀሙ','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'ሲነቃ፣ በቼክአውት ላይ ያለው የፒክአፕ አማራጭ መለያ ከWooCommerce picack location settings ርዕስ ጋር ይዛመዳል። ሲሰናከል፣ መለያው ከFluid Checkout የሚተረጎመውን &quot;Local pickup&quot; ጽሑፍ ይጠቀማል።','Button label for applying coupon codesApply' => 'ያመልክቱ','Checkout step titleContact' => 'ተገናኝ','Checkout step titleShipping' => 'መላኪያ','Checkout step titleBilling' => 'የሂሳብ አከፋፈል','Checkout step titlePayment' => 'ክፍያ','Checkout substep change link labelChange' => 'ለውጥ','Checkout substep save link labelSave changes' => 'ለውጦችን ያስቀምጡ','Substep review textNone.' => 'ምንም።','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s፡ %1$s','Image uploader.No image selected.' => 'ምንም ምስል አልተመረጠም።','Settings sectionCart' => 'ጋሪ','Settings sectionOrder pay' => 'ክፍያን ማዘዝ','Settings sectionThank you' => 'አመሰግናለሁ','Settings section titleIntegrations' => 'ውህደቶች','Settings section titleLicense keys' => 'የፍቃድ ቁልፎች','Captcha positionBefore place order section' => 'የትዕዛዝ ክፍል በፊት','Captcha positionBefore place order button' => 'የትዕዛዝ አዝራር በፊት','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'ገጠመ','Log in link label at checkout contact stepLog in' => 'ግባ','Log in separator label at for when guest checkout is disabledOr continue below' => 'ወይም ከታች ይቀጥሉ','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'ወይም እንደ እንግዳ ቀጥል','Clear image selection on admin pages.Remove image' => 'ምስል አስወግድ','shipping packagesShipping %d' => '%d መላኪያ','shipping packagesShipping' => 'ጭነት','Used as fallback for "Proceed to next step" button labelnext step' => 'ቀጣዩ እርምጃ','Substep review checkbox value